insert into public.estudos (org_id, id, nome, programa, acao, resumo, rotulo_bloco, rotulo_plural,
                            focal_area, focal_pessoa, focal_email, do_relatorio, ordem) values
  ('seab', 'p1', 'Programa Leite das Crianças (PLC)', 'Programa Leite das Crianças (PLC)', 'Ação orçamentária 8258, Direito Humano à Alimentação Adequada', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado ao Programa Leite das Crianças, política de segurança alimentar que distribui 1 litro diário de leite a crianças de 6 a 36 meses de famílias inscritas no CadÚnico. O programa responde por 76,4% do orçamento liquidado da ação 8258 em 2025, o equivalente a R$ 138,9 milhões."],["Objetivo da análise","Examinar a relação entre os recursos aplicados e os resultados entregues pelo programa, verificando não apenas quanto se gasta, mas o que se entrega com esses recursos e se o modelo de entrega vigente é o mais eficiente e efetivo disponível."],["O que foi analisado","Três eixos: o custo-benefício da entrega frente a formatos alternativos, as causas da queda de cobertura e as medidas corretivas, e o desenvolvimento de instrumento de pesquisa junto aos beneficiários. As análises usaram dados administrativos do programa, comparações com o mercado e com programas estaduais análogos."],["Resultado esperado","Reverter a trajetória de queda da cobertura, de 46,9% em 2023 para 36,3% em 2026, com mais de 141 mil crianças elegíveis não alcançadas, e qualificar o modelo operacional e os controles de distribuição, gerando subsídios para a proposta orçamentária da ação 8258."]]'::jsonb, null, null, '', '', '', true, 1),
  ('sedest', 'p1', 'Projeto Parques Urbanos', 'Projeto Parques Urbanos', 'Ação orçamentária 8206, Gestão de Recursos Hídricos, Resíduos Sólidos e Saneamento Ambiental', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado ao Projeto Parques Urbanos, linha de ação do Programa Estadual Paraná Mais Verde, executado pela SEDEST com o Instituto Água e Terra e os municípios. Entre 2019 e 2025 foram 91 convênios e R$ 126,2 milhões conveniados, dos quais R$ 81,1 milhões já executados, em mais de 4,2 milhões de metros quadrados de área de projeto."],["Objetivo da análise","Responder à pergunta norteadora do estudo: como aumentar a eficiência da aplicação dos recursos do Projeto Parques Urbanos. A ferramenta adotada foi a Análise de Desempenho Físico-Financeiro, voltada a aferir a coerência entre o recurso executado e a entrega física."],["O que foi analisado","Três temas, com base nas 52 obras encerradas: a dispersão do custo por metro quadrado de área recuperada, o prazo entre a assinatura do convênio e a entrega, e a evolução de indicadores ambientais antes e depois das obras. O estudo resultou no Painel de Análise do Projeto Parques Urbanos."],["Resultado esperado","Critérios objetivos de seleção e de acompanhamento, com faixas de custo de referência por porte da obra e prazo padrão de 36 meses ante a mediana atual de 40,7, permitindo atender mais parques com a mesma dotação, e medição de resultado por dados primários coletados em campo."]]'::jsonb, null, null, '', '', '', true, 1),
  ('sesa', 'p1', 'Processos de aquisição de medicamentos', 'Processos de aquisição de medicamentos', 'Centro de Medicamentos do Paraná (CEMEPAR), 530 processos e R$ 2,74 bilhões entre 2023 e 2025', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado ao mapeamento e ao redesenho dos processos de aquisição de medicamentos da SESA, conduzidos pelo Centro de Medicamentos do Paraná (CEMEPAR). A base analisada cobre 530 processos de aquisição e cerca de R$ 2,74 bilhões adquiridos entre 2023 e 2025."],["Objetivo da análise","Identificar como aprimorar a eficiência dos processos administrativos de aquisição, mapeando gargalos, prazos de tramitação, modalidades de compra e pontos de fragilidade no abastecimento. O estudo não avaliou a política de assistência farmacêutica em sua totalidade nem efeitos sobre indicadores finais de saúde."],["O que foi analisado","Oito fluxos foram mapeados na situação vigente, sete receberam proposições de redesenho e seis tiveram alterações estruturais no encadeamento das atividades. O trabalho incluiu ainda a definição de indicadores de desempenho e a construção de um painel de monitoramento alimentado pelas bases do CEMEPAR. A ferramenta adotada foi a Avaliação Express, de nível básico no modelo de Orçamento para Resultados."],["Resultado esperado","Reduzir gargalos e tempos de tramitação, padronizar a instrução processual, substituir controles manuais por registros digitais e institucionalizar o acompanhamento por indicadores, com rito bimestral de análise crítica conduzido pelo CEMEPAR."]]'::jsonb, null, null, 'Centro de Medicamentos do Paraná (CEMEPAR)', '', '', true, 1),
  ('seed', 'p1', 'Despesas com água e energia elétrica da Rede Pública Estadual de Ensino', 'Despesas com água e energia elétrica da Rede Pública Estadual de Ensino', 'Ação orçamentária 8470, Gestão Administrativa das Unidades Escolares', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado às despesas com água e energia elétrica das escolas estaduais, custeio recorrente estimado em cerca de R$ 67,9 milhões anuais na água e R$ 67,3 milhões na energia, distribuído por 2.088 unidades escolares."],["Objetivo da análise","Identificar, entre unidades comparáveis, onde o gasto por aluno se afasta do padrão esperado e qual o potencial de racionalização associado. A ferramenta adotada foi a Gestão Matricial de Despesas, que confronta os pacotes de despesa com as unidades que os executam."],["O que foi analisado","A rede foi organizada em catorze agrupamentos por porte e regime de funcionamento, condição para comparar escolas estruturalmente semelhantes. Sobre essa base foram analisadas 1.499 escolas com indicador válido de água e 1.879 de energia, e construído um painel interativo de consumo por aluno."],["Resultado esperado","Reduzir o gasto das unidades mais distantes do padrão dos seus pares, de forma faseada e sem corte linear, com prioridade a poucas escolas de consumo extremo na água e cobertura ampla do quarto quartil na energia, precedida de verificação de campo e auditoria cadastral."]]'::jsonb, null, null, '', '', '', true, 1),
  ('seil', 'p1', 'Programa Construindo o Paraná Digital', 'Programa Construindo o Paraná Digital', 'Sem ação orçamentária específica, vinculado como entrega da ação administrativa 8300', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado ao Programa Construindo o Paraná Digital, que compõe equipes técnicas de arquitetura e engenharia nas 19 Associações de Municípios do Paraná, capacita esses profissionais na metodologia BIM e prevê a entrega de 1.230 projetos ao longo dos quatro anos de implementação."],["Objetivo da análise","Estruturar os elementos de monitoramento de um programa ainda em fase de concepção, que não dispunha de indicadores de desempenho, de entregas mensuráveis consolidadas nem de sistemática de monitoramento e avaliação formalizada."],["O que foi analisado","Dois eixos: a definição de indicadores de desempenho para o acompanhamento contínuo ao longo dos quatro anos de implementação, e a definição de um indicador de efetividade, a Taxa de celebração de convênios, apurado semestralmente a partir do penúltimo ano de execução e ao longo dos dois anos subsequentes ao encerramento do programa. Cinco indicadores foram validados."],["Resultado esperado","Permitir que a SEIL acompanhe as entregas com evidências, preste contas de forma estruturada à SEFA e aos órgãos de controle e verifique, por meio do indicador de efetividade, em que medida os projetos elaborados pelas associações resultam em convênios celebrados com o Governo do Estado."]]'::jsonb, null, null, '', '', '', true, 1),
  ('seti', 'p1', 'Painel de Indicadores das Universidades Estaduais do Paraná', 'Painel de Indicadores das Universidades Estaduais do Paraná', 'Ações de gestão das sete Instituições Estaduais de Ensino Superior, no orçamento de R$ 4,49 bilhões da SETI em 2025', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado ao monitoramento e à análise comparativa de indicadores das sete Instituições Estaduais de Ensino Superior do Paraná, que concentram parcela expressiva do orçamento da SETI, de R$ 183,2 milhões na UENP a R$ 847,9 milhões na UEM em 2025. O plano de ação do relatório tem caráter preliminar e será validado com a Secretaria na etapa de pactuação dos encaminhamentos."],["Objetivo da análise","Construir uma base integrada de evidências que relacione recursos, características institucionais e indicadores acadêmicos das sete universidades, enfrentando a fragmentação das informações em diferentes bases e a dificuldade de comparar instituições de perfis estruturais distintos, sem o propósito de produzir uma medida única de eficiência da gestão universitária."],["O que foi analisado","Três eixos: mapeamento e consolidação dos indicadores comuns às sete instituições, considerando os previstos no art. 64 da Lei Geral das Universidades e outras bases oficiais; construção de uma base integrada que relacione informações acadêmicas, institucionais e orçamentárias de forma padronizada; e mecanismos de contextualização das comparações, incluindo a clusterização multidimensional das universidades estaduais brasileiras. O estudo resultou no Painel de Indicadores das Universidades Estaduais do Paraná, com nove abas, 107 indicadores e catorze bases de dados."],["Resultado esperado","Incorporar o painel como instrumento permanente de monitoramento e apoio à decisão no ciclo orçamentário das universidades, sem que índices e rankings sejam usados de forma isolada ou automática como critério de redução, ampliação ou redistribuição de recursos."]]'::jsonb, null, null, '', '', '', true, 1),
  ('der', 'p1', 'Gestão da Manutenção Rodoviária', 'Gestão da Manutenção Rodoviária', 'Ação orçamentária 8398, Administração da manutenção e segurança do sistema rodoviário estadual', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado à gestão da manutenção rodoviária no âmbito da Ação 8398, maior ação orçamentária do DER, com R$ 1,19 bilhão em 2025. A análise concentrou-se nos 46 contratos de manutenção e conservação de pavimentos das cinco Superintendências Regionais, que somaram cerca de R$ 869,5 milhões liquidados, 72,8% do total liquidado da ação. O relatório é preliminar e o plano de ação ainda depende de detalhamento e pactuação com o DER."],["Objetivo da análise","Verificar como a intensidade do gasto nos contratos de manutenção e conservação de pavimentos se relaciona com a condição observada da malha em cada Superintendência Regional, e em que medida a distribuição dos recursos se mostra aderente à criticidade técnica identificada, sem atribuir relação causal entre gasto e condição."],["O que foi analisado","Quatro dimensões comparadas entre as cinco Superintendências Regionais: intensidade do gasto, medida pelo valor liquidado por quilômetro de extensão contratada; condição observada da malha, pelo levantamento SAM 2025 e pelos indicadores de irregularidade superficial e de capacidade estrutural do pavimento de 2021 e 2022; aderência alocativa; e sinais de pressão futura. O estudo resultou no Painel de Execução e Condição da Malha."],["Resultado esperado","Incorporar o painel como instrumento permanente de monitoramento na gestão orçamentária do DER, apoiando a identificação de regionais e contratos que demandem análise técnica adicional, sem que seja usado como critério automático de corte ou redistribuição de recursos entre regionais."]]'::jsonb, null, null, '', '', '', true, 1),
  ('sedef', 'p1', 'Transferência de recursos para OSCs no Edital nº 005/2024', 'Transferência de recursos para OSCs no Edital nº 005/2024', 'Ação orçamentária 8418, Políticas Públicas da Criança e do Adolescente', '[["Do que se trata","Estudo da Qualidade do Gasto do programa Orçamento para Resultados, aplicado ao Edital de Chamamento Público nº 005/2024, por meio do qual a SEDEF financia projetos de Organizações da Sociedade Civil (OSCs) voltados à proteção e à promoção dos direitos de crianças e adolescentes, em seis eixos temáticos alinhados ao Estatuto da Criança e do Adolescente. O edital recebeu 1.527 propostas, das quais 1.238 foram consideradas aptas, e conta com R$ 200 milhões deliberados. É financiado pela Ação 8418, de escopo mais amplo que o edital."],["Objetivo da análise","Compreender não apenas o volume desembolsado, mas como os recursos do edital se distribuem entre projetos, eixos e territórios, quais entregas são financiadas e, progressivamente, quais resultados são produzidos pelas parcerias. A abordagem adotada foi a análise de desempenho físico-financeiro, complementada por análises do processo de seleção e repasse e da distribuição territorial dos recursos."],["O que foi analisado","Seis indicadores, com dados até maio de 2026: taxa de aptidão das propostas (81,1%), execução financeira por eixo (315 propostas pagas e R$ 80,6 milhões desembolsados, com taxas de cerca de 23% nos Eixos 1 e 4 a 35,7% no Eixo 3), aderência ao valor teto, cobertura territorial (113 dos 399 municípios), ritmo de desembolso mensal e prazo total do ciclo do edital (234 dias da abertura ao primeiro pagamento). O estudo resultou no Painel Executivo do Edital nº 005/2024."],["Resultado esperado","Avançar progressivamente da leitura da execução financeira para análises de custo, entrega e resultado, com o registro estruturado de público atendido, metas e entregas de cada parceria; reduzir esforços administrativos das OSCs e das equipes da SEDEF; e usar as informações de desempenho como insumo complementar nas discussões orçamentárias entre a SEFA e a SEDEF, sem critérios automáticos de alocação."]]'::jsonb, null, null, '', '', '', true, 1)
on conflict (org_id, id) do nothing;

insert into public.recomendacoes (org_id, estudo_id, rid, numero, titulo, chamada, icone, cor, fonte,
                                  quadro, paragrafos, do_relatorio) values
  ('seab', 'p1', 'r1', 1, 'Recomendações para ampliação da cobertura', 'Busca ativa, campanha de comunicação, cadastramento e pesquisa com beneficiários.', 'usuarios', null, 'Seção 4.2.1 do Relatório Final do Estudo da Qualidade do Gasto', 'Quadro 6. Plano de ação para ampliação da cobertura e busca ativa', '["A principal prioridade de intervenção identificada pelo Estudo da Qualidade do Gasto é a reversão da trajetória de queda no número de beneficiários. Para tanto, recomenda-se a implementação de um conjunto integrado de ações, organizadas segundo seu horizonte de implementação.","No curto prazo, com impacto potencial mais imediato, recomenda-se fortalecer os mecanismos de busca ativa de famílias elegíveis, por meio da articulação formal com as secretarias municipais de saúde e assistência social. Os agentes comunitários de saúde e os técnicos dos CRAS são atores estratégicos para a identificação e o encaminhamento de famílias que deveriam estar inscritas no programa. Essa articulação não requer alterações normativas ou investimentos significativos, mas exige a definição de responsabilidades claras e de fluxos de comunicação entre os órgãos envolvidos.","Ainda no curto prazo, recomenda-se a realização de campanha de comunicação orientada ao público elegível, com linguagem acessível e canais diversificados, incluindo os pontos de entrega do leite, unidades de saúde, CRAS, escolas e aplicativos de comunicação já utilizados pelas secretarias municipais. A campanha deve comunicar claramente os critérios de elegibilidade, o processo de cadastramento, os pontos de entrega e os benefícios do programa, reduzindo as barreiras informacionais identificadas como hipótese relevante de explicação para a baixa cobertura.","No médio prazo, recomenda-se o aprimoramento do processo de cadastramento e recadastramento de beneficiários, com objetivo de reduzir as barreiras administrativas e operacionais ao ingresso e à permanência no programa. Nesse sentido, deve-se mapear os gargalos existentes nos fluxos municipais de cadastramento, identificar os pontos de perda de beneficiários ao longo do processo (desde o primeiro contato com o programa até a efetiva ativação do benefício) e implementar melhorias procedimentais para simplificação e desburocratização do acesso.","A realização da pesquisa com beneficiários e público elegível não atendido, cujo instrumento foi desenvolvido no âmbito do Estudo da Qualidade do Gasto, é passo fundamental para qualificar o diagnóstico sobre as barreiras de acesso e orientar as ações de melhoria. Os dados primários obtidos por meio da pesquisa permitirão validar ou refutar as hipóteses formuladas e identificar os fatores de maior impacto sobre a adesão e permanência no programa nos diferentes perfis de município."]'::jsonb, true),
  ('seab', 'p1', 'r2', 2, 'Recomendações para aprimoramento do modelo operacional', 'Controle da distribuição, novos canais de entrega e critérios de elegibilidade.', 'ajustes', null, 'Seção 4.2.2 do Relatório Final do Estudo da Qualidade do Gasto', 'Quadro 7. Plano de ação para aprimoramento do modelo operacional e dos controles de distribuição', '["Para qualificar a entrega do programa e fortalecer os controles operacionais, recomenda-se a implementação de um sistema de controle regular da distribuição e da dispensação de leite aos beneficiários. Atualmente, há lacunas no acompanhamento do fluxo desde o ponto de entrega até a família beneficiária, o que limita a capacidade do programa de identificar irregularidades, quantificar perdas e garantir a regularidade da distribuição. A adoção de registros digitais nos pontos de entrega, com confirmação de retirada pelos beneficiários, representaria avanço significativo na rastreabilidade da distribuição.","Recomenda-se também estudar a viabilidade de inclusão de entes da administração pública e de entidades beneficentes como canais adicionais de distribuição do leite. O Sistema de Registro de Preços do Estado conta com contratos vigentes de fornecimento de leite para outros órgãos públicos, com preços variando de R$ 4,85 a R$ 5,67 por litro. A análise dessa alternativa poderia ampliar o alcance do programa sem aumentar o custo unitário de aquisição, desde que o modelo logístico de distribuição seja adequadamente estruturado.","Em relação aos critérios de elegibilidade, a análise conduzida não recomenda alterações imediatas na faixa etária (6 a 36 meses), que está bem fundamentada sob o ponto de vista nutricional. Para o critério de renda, recomenda-se uma análise aprofundada da composição do público elegível não atendido, com cruzamento dos dados do CadÚnico, antes de qualquer alteração. Caso a análise confirme que a hipótese de exclusão por barreiras de acesso administrativo é relevante, a estratégia mais eficiente é reduzir essas barreiras (por meio de busca ativa e simplificação do cadastramento) antes de considerar ajustes no critério de renda."]'::jsonb, true),
  ('sedest', 'p1', 'r1', 1, 'Dispersão do custo construtivo', 'Custo por metro quadrado lido como tipologia da obra e comparação por faixa de porte.', 'moeda', '214 72% 44%', 'Seção 5.1 do Relatório Final do Estudo da Qualidade do Gasto', 'Quadro 4. Consolidação das ações recomendadas, responsáveis e prazos', '["Análise: Ao isolar o quartil de menor custo por m² (13 obras encerradas, de R$ 7,90/m² (Andirá) a R$ 20,00/m² (Tapejara)) e estudar caso a caso o que essas obras têm em comum, emergem três marcas convergentes. Primeira: são as grandes áreas, com área mediana de 57.214 m², 8,7 vezes a do quartil de maior custo (6.548 m²); os casos extremos estão entre os maiores parques do projeto, como Jussara (88.185 m²) e São João do Ivaí (84.828 m²). Segunda: são a safra inaugural, pois 10 das 13 obras foram conveniadas em 2019, o primeiro lote, sugerindo que os municípios pioneiros capturaram os grandes terrenos de fundo de vale disponíveis. Terceira: a contrapartida municipal mediana desse quartil é de exatamente 2,0%, o piso do projeto, ou seja, as obras de menor custo por m² não são as de maior esforço financeiro local, e sim as de aporte mínimo. Por ora, portanto, parece haver uma tendência de melhor desempenho em custo por m² associada às grandes áreas dos primeiros convênios, com uma hipótese explicativa plausível: o custo de implantar um parque tende a ser relativamente fixo (próximo de R$ 1 milhão por obra) e se dilui em muita área quando o terreno é grande. Ainda não é possível, contudo, cravar uma relação direta de que maior área significa maior eficiência: a amostra de obras encerradas é pequena (52 obras) e fortemente concentrada no ciclo de 2019, de modo que o efeito de escala se confunde com a especificidade do primeiro corte. Apenas com o encerramento de obras dos ciclos seguintes, a amostra se ampliará o suficiente para distinguir com segurança o que é efeito de escala, o que é particularidade da safra inaugural e o que é, de fato, eficiência de gestão.","Recomendação: Tratar, por enquanto, o custo por m² como indicador descritivo de tipologia da obra (parque extenso de fundo de vale versus parque urbano compacto), e não como ranking definitivo de mérito municipal. Ao avaliar eficiência de gestão, comparar municípios dentro de faixas semelhantes de área de projeto e reavaliar os critérios de eficiência à medida que as obras dos cortes 2024 e 2025 forem encerrando e ampliando a base de comparação, verificando inclusive se há esgotamento de áreas amplas disponíveis nas safras recentes.","Resultado esperado: Critérios de eficiência mais bem fundamentados a partir de uma amostra ampliada e equilibrada entre ciclos, capaz de separar o efeito-tamanho do efeito-gestão e de evitar que municípios com parques pequenos e bem executados sejam precocemente classificados como ineficientes. Prazo estimado: 3 a 4 anos, ao encerramento das primeiras obras dos cortes 2024 e 2025. Em termos de valor, critérios de eficiência mais bem calibrados permitem direcionar a seleção de municípios e o dimensionamento de recursos para obter mais área de parque recuperada por real investido, qualificando a alocação sem aumento de dotação."]'::jsonb, true),
  ('sedest', 'p1', 'r2', 2, 'Prazo de execução e porte da obra', 'Prazo de referência de 36 meses, acompanhamento ativo da execução e registro dos marcos.', 'relogio', '40 82% 50%', 'Seção 5.2 do Relatório Final do Estudo da Qualidade do Gasto', 'Quadro 4. Consolidação das ações recomendadas, responsáveis e prazos', '["Análise: A hipótese intuitiva de que obras maiores demoram mais não se sustenta nos dados das 52 obras encerradas. A correlação de Spearman entre a duração total, da assinatura do convênio à finalização, e a área do projeto é de apenas +0,32 (uma relação fraca). A correlação de Spearman é uma medida estatística que varia de -1 a +1 e indica se duas variáveis se movem juntas pela ordem de seus postos: valores próximos de +1 significam que, quanto maior uma, maior a outra; próximos de 0 indicam ausência de relação; e negativos indicam relação inversa. O +0,32 obtido, portanto, diz que área e prazo crescem juntos apenas de forma tênue, longe de uma relação de causa direta. Com o valor executado a associação é ainda menor, +0,22. O tempo mediano de implantação é de 40,7 meses (cerca de 3,4 anos), mas a dispersão é ampla, de 17 a 72 meses, e mal explicada pelo porte. Os casos demonstram isso com clareza: Cianorte entregou o maior parque do projeto, 157.858 m², em 38 meses, e Andirá entregou 68.084 m² em apenas 24 meses; Campo Mourão executou 92.072 m² em 33 meses e Jussara 88.185 m² em 31 meses. No sentido oposto, as obras mais lentas são de porte médio, como Formosa do Oeste (72 meses para 34.253 m²), Nova Londrina (71 meses para 40.000 m²) e Pitanga (62 meses para apenas 24.800 m²). Doze obras foram simultaneamente grandes, acima da mediana de área, e rápidas, abaixo da mediana de prazo, o que descarta o tamanho como gargalo. Se não é o porte, o fator explicativo parece apontar para a capacidade de execução do município, condução da licitação, fiscalização e fluxo de repasse. Um sinal complementar reforça a hipótese: as duas obras de maior contrapartida municipal, Pitanga (62 meses) e Umuarama (60 meses), com 31,5% e 27,1% contra um piso de 2%, estão também entre as mais lentas do projeto, sugerindo que arranjos de cofinanciamento mais pesados podem se associar a obras mais complexas ou de execução mais arrastada. Vale aqui a mesma ressalva da análise anterior: estes 52 encerrados concentram-se no ciclo de 2019, e a leitura de que a gestão local, e não o porte, governa o prazo é, por ora, uma tendência consistente, mas não um veredito; só poderá ser confirmada à medida que as obras dos cortes seguintes encerrarem e ampliarem a base de comparação.","A base registra, para cada convênio, três datas: a de assinatura, a de início da obra e a de finalização. A partir delas, o prazo total, da assinatura à finalização, separa-se em duas fases. A primeira, da assinatura ao início da obra, compreende a preparação do projeto executivo, a licitação e a contratação; tem mediana de 5,4 meses e varia de 0,9 a 11,9 meses, sem nenhum caso superior a um ano. A segunda, do início à finalização, corresponde à execução física da obra; tem mediana de 33,8 meses e varia de 15,7 a 68,6 meses. Em cada obra, a fase que antecede o início físico representa, na mediana, cerca de 13% do prazo total, cabendo os aproximadamente 87% restantes à execução da obra propriamente dita. Praticamente toda a dispersão observada no prazo total origina-se, portanto, na fase de execução. As seis obras que superaram 60 meses ilustram o ponto: sua fase preparatória durou entre 2,1 e 11,9 meses, dentro da faixa geral do projeto, enquanto a execução física consumiu entre 53,9 e 68,6 meses. Cabe a ressalva de que a base registra apenas essas três datas, de modo que eventuais tratativas anteriores à celebração do convênio não são capturadas. Ainda assim, o registro disponível indica que o esforço de fortalecimento da gestão municipal tende a produzir maior efeito quando dirigido à condução da obra já contratada.","Recomendação: Estabelecer um prazo de referência de implantação independente do porte da obra, por exemplo 36 meses da assinatura à entrega, contra a mediana atual de 40,7 meses, e direcionar acompanhamento técnico ativo à fase de execução das obras, em vez de presumir que parques grandes serão lentos. Investigar individualmente as obras acima de 60 meses, Formosa do Oeste, Nova Londrina, Nova Olímpia, Boa Ventura de São Roque, Pitanga e Umuarama, para identificar os gargalos recorrentes e checar a relação entre contrapartida elevada e maior prazo.","Como o prazo é governado pela capacidade de gestão municipal, a referência de 36 meses precisa vir acompanhada de medidas que atuem sobre essa capacidade, sob pena de converter-se em exigência sem a devida contrapartida de apoio. O desenho dessas medidas deve considerar uma característica estrutural do portfólio: dos 87 municípios atendidos, 83 celebraram um único convênio e apenas quatro celebraram dois, de modo que praticamente todo município é estreante no projeto e não há aprendizado acumulado localmente a ser aproveitado. Como a dispersão de prazo se concentra na fase de execução física, recomendam-se três medidas dirigidas a essa fase. A primeira, de maior efeito esperado, é o apoio à fiscalização e à gestão contratual da obra, com rotina de medição periódica, designação formal de responsável pelo acompanhamento no município e agenda regular de acompanhamento técnico do IAT, presencial ou remoto. A segunda é o registro, na base do projeto, dos marcos intermediários da execução, como publicação do edital, homologação, ordem de serviço, medições e eventuais paralisações com o respectivo motivo, informação hoje ausente e sem a qual o gargalo específico de cada obra não pode ser localizado com precisão. A terceira é a calibragem da intensidade do acompanhamento por fatores objetivos de risco da obra, e não pelo histórico do município, uma vez que a ausência de histórico é a regra no projeto e não distingue casos.","Resultado esperado: Redução da amplitude de prazos, hoje de 17 a 72 meses, e da mediana de 40,7 meses, com foco na capacidade de gestão municipal e não em restrição ao porte. Prazo estimado: 2 a 4 anos, ao acompanhamento das obras dos cortes 2024 e 2025. Das 52 obras concluídas, 62% superaram 36 meses e 6 ultrapassaram 60 meses; adotar a referência de 36 meses, ante a mediana atual de 40,7, anteciparia em cerca de cinco meses a entrega de cada parque à população, ampliando o resultado gerado com os mesmos recursos. O efeito das medidas de fortalecimento da gestão municipal tende a se concentrar na fase de execução física, que responde pela maior parte do prazo e por praticamente toda a sua dispersão, e sua aferição dependerá do registro dos marcos intermediários ora recomendado."]'::jsonb, true),
  ('sedest', 'p1', 'r3', 3, 'Evolução da cobertura florestal no antes e depois das obras', 'Coleta de dados primários no parque e confirmação da atribuição do ganho ambiental à obra.', 'folha', '147 67% 37%', 'Seção 5.3 do Relatório Final do Estudo da Qualidade do Gasto', 'Quadro 4. Consolidação das ações recomendadas, responsáveis e prazos', '["Análise: Entre os sete indicadores de resultado acompanhados, o que combina a maior cobertura de obras com janela antes-e-depois e um sinal interpretável é o Remanescente Florestal (%), que é também o indicador tematicamente mais alinhado ao projeto, dado que os convênios exigem plantio de vegetação nativa da Mata Atlântica. Ele dispõe de medição pré e pós-obra para 28 municípios com obra encerrada (os demais não têm pontos suficientes antes ou depois). Em 22 desses 28 municípios (79%), o remanescente florestal subiu após a obra, com variação mediana de +0,15 ponto percentual. Os ganhos são modestos em magnitude, os maiores são Guaíra (+0,67 p.p.), Rondon (+0,54 p.p.) e Jussara (+0,44 p.p.), com Santa Isabel do Ivaí (+0,36 p.p.) também entre os avanços, enquanto uma minoria registrou queda, como Ventania (-0,56 p.p.) e Sapopema (-0,34 p.p.). Um ponto importante para não repetir o erro de atrelar resultado a tamanho: a melhora florestal não está fortemente associada nem à área nem ao custo da obra, com correlações de Spearman fracas (+0,16 com a área e -0,20 com o custo por m²); ou seja, os grandes parques baratos por m² não entregaram sistematicamente mais ganho florestal que os pequenos. O percentual de remanescente é uma medida municipal apenas indicativa para captar um parque de poucos hectares (problema de atribuição), a série é bienal, as variações são pequenas e parte do movimento pode refletir dinâmicas regionais de uso do solo alheias ao parque. Assim, a melhora direcional em 79% dos municípios é um sinal encorajador, não uma prova de efeito causal, e tende a se firmar à medida que mais obras encerrarem e as janelas pós-obra se alongarem.","Recomendação: Investigar por que justamente o remanescente florestal melhora enquanto os demais indicadores não acusam ganho, distinguindo duas hipóteses concorrentes: ou o efeito do parque se manifesta de fato primeiro na cobertura vegetal, coerente com a exigência de plantio de nativas, ou os outros indicadores apenas não dispõem de dado com densidade e sensibilidade suficientes para captar mudança (caso de alagamento, com ocorrências quase sempre nulas, e de cursos d''água com parques lineares, praticamente sem série). Em paralelo, confirmar se a alta de remanescente é atribuível ao parque ou à tendência regional de uso do solo, comparando cada município com seus vizinhos não atendidos. Sobretudo, instituir a coleta de dados primários, locais ao parque e hoje ausentes, área efetivamente plantada, número de mudas e taxa de sobrevivência, área recuperada e permeável, que são formas de medir a melhora com mais precisão, em vez de depender de proxies municipais.","Resultado esperado: Compreensão do mecanismo por trás da melhora florestal e diagnóstico claro de quais indicadores realmente estagnaram e quais apenas carecem de dados, sustentado por informação primária coletada em campo. Prazo estimado: 2 a 3 anos para o diagnóstico e a estruturação da coleta primária; 4 a 6 anos para a leitura de impacto consolidada."]'::jsonb, true),
  ('sedest', 'p1', 'r4', 4, 'Otimização dos recursos', 'Gatilhos objetivos de seleção e acompanhamento, com faixas de custo de referência por porte.', 'alvo', '194 85% 38%', 'Seção 5.4 do Relatório Final do Estudo da Qualidade do Gasto', 'Quadro 4. Consolidação das ações recomendadas, responsáveis e prazos', '["As recomendações das seções 5.1 a 5.3 já constituem, por si, critérios de otimização dos recursos do projeto: sua adoção eleva o resultado obtido por real investido sem exigir ampliação da dotação. Mais do que diagnósticos, esses achados podem ser convertidos em gatilhos objetivos de seleção e de acompanhamento, aplicados na entrada do convênio e ao longo da execução.","Da análise de dispersão do custo construtivo (5.1) deriva-se um custo por metro quadrado de referência, definido por faixa de porte da obra, a operar como gatilho de seleção. Projetos cujo custo unitário se situe dentro da faixa de referência de sua classe de área seriam aceitos diretamente; os que a excedam exigiriam justificativa técnica que demonstre a necessidade de maior investimento, como condições do terreno, fundação, drenagem ou contenção. O custo deixa, assim, de ser apenas descritivo e passa a orientar a decisão, sem penalizar obras de maior complexidade desde que tecnicamente justificadas. Para viabilizar a aplicação imediata do critério, propõem-se faixas iniciais de custo por metro quadrado de referência, calculadas a partir das 52 obras encerradas com área e valor registrados e organizadas em quatro classes de porte, conforme o Quadro 2. Em cada classe, adota-se a mediana observada como custo de referência e o terceiro quartil como teto de referência, acima do qual se aplica a exigência de justificativa técnica já descrita. As faixas confirmam a relação identificada na seção 5.1, de que o custo por metro quadrado cai acentuadamente à medida que a área cresce, uma vez que o custo de implantar um parque é relativamente fixo, com investimento mediano em torno de R$ 1,0 milhão por obra, e se dilui em maior área nos parques mais extensos.","Esses parâmetros constituem proposta inicial, e não valores definitivos. Derivam de amostra pequena e concentrada no primeiro ciclo do projeto, com 28 das 52 obras encerradas conveniadas em 2019, e são especialmente frágeis na classe de maior porte, que reúne apenas seis obras, e na de menor porte, a mais dispersa, em que o custo por metro quadrado varia de R$ 60 a R$ 1.126. Tanto o recorte das faixas de porte quanto a adoção do terceiro quartil como teto de referência resultam da distribuição dos dados hoje disponíveis e podem ser ajustados pelas partes interessadas, SEDEST, IAT e SEFA, caso considerem pertinente adotar recorte ou limiar diverso. Recomenda-se que as faixas sejam recalibradas a cada ciclo orçamentário, à medida que as obras dos cortes de 2024 e 2025 encerrarem e ampliarem a base de comparação. A definição e a atualização periódica dos parâmetros caberiam à SEDEST, no plano da política, e ao IAT, no plano técnico, que dispõem, na aba Eficiência do Investimento do painel, do cálculo automatizado dessas estatísticas por faixa de porte. Consolidados em uma planilha orçamentária referencial padronizada, disponibilizada pelo Estado ao município aderente, os valores tornam-se um parâmetro vivo, atualizado com o próprio avanço do projeto, e não uma referência estática. Essa planilha integra um conjunto padronizado de instrumentos de apoio, como estrutura de termo de referência, modelo de edital e catálogo de especificações técnicas, entendido como base comum de referência, e não como projeto único, e cuja adoção consta do quadro de governança.","Da análise de prazo de execução (5.2) deriva-se um prazo máximo de referência de 36 meses, da assinatura à entrega, como gatilho de acompanhamento. Seu cumprimento seria exigência padrão do convênio, e prazos superiores demandariam justificativa técnica e acompanhamento ativo. A medida ataca diretamente a dispersão observada, de mediana de 40,7 meses, com 62% das obras encerradas acima de 36 meses, e reduz o tempo de imobilização de recursos já empenhados.","Da análise dos indicadores de resultado (5.3) deriva-se menos um gatilho de entrada e mais a necessidade de aprimorar a medição dos resultados do projeto. A análise evidenciou que os indicadores municipais hoje disponíveis não captam com precisão o efeito de um parque e recomendou instituir a coleta de dados primários, locais a cada obra, como área efetivamente plantada, número de mudas, taxa de sobrevivência e área recuperada e permeável. Estruturada essa coleta, torna-se possível avaliar periodicamente, e não uma única vez, se o projeto está de fato colaborando com a melhora da sustentabilidade que se propõe a atingir, distinguindo os arranjos que entregam resultado ambiental efetivo daqueles que não o fazem.","Em conjunto, esses critérios atuam em três momentos do ciclo da obra. Na seleção, anterior à celebração, o custo por metro quadrado de referência tria e disciplina a aceitação dos convênios. Durante o acompanhamento, o prazo máximo de 36 meses e o monitoramento ativo orientam a execução. Após a obra, a avaliação de resultado, sustentada pelos dados primários coletados, afere a eficácia e orienta a calibragem dos parâmetros nos ciclos seguintes, em coerência com o caráter contínuo do Orçamento para Resultados.","Esses três critérios não substituem, mas reforçam, os parâmetros que o projeto já adota. O critério de seleção por custo por metro quadrado somar-se-ia aos critérios de elegibilidade hoje vigentes, predominantemente técnicos, jurídicos e ambientais, como a titularidade do terreno, a apresentação de projeto com Anotação de Responsabilidade Técnica, a localização em área degradada de fundo de vale e o plantio mínimo de vegetação nativa da Mata Atlântica, bem como ao critério de desempate que hoje favorece os municípios de menor IDH-PNUD, acrescentando-lhes uma dimensão de eficiência econômica de que a seleção ainda não dispõe.","O critério de prazo máximo de 36 meses reforçaria o acompanhamento que o projeto já exerce por meio do cronograma físico-financeiro e da liberação de repasses conforme a progressão da obra, ao oferecer um parâmetro objetivo de tempo.","Os critérios de avaliação, por fim, somando os indicadores já existentes no painel aos dados primários a serem coletados em campo, auxiliariam no rastreio dos resultados de sustentabilidade que o projeto se propõe a entregar à sociedade, como a recuperação de áreas degradadas, a proteção dos recursos hídricos, a ampliação de áreas verdes e a redução de processos erosivos e de inundação. O quadro a seguir sintetiza os três critérios, o momento de aplicação e os parâmetros de referência sugeridos."]'::jsonb, true),
  ('sesa', 'p1', 'r1', 1, 'Alterações no fluxo de aquisição', 'Mudanças no encadeamento das atividades dos fluxos redesenhados: DFD antes do ETP, cotação integral dos itens e validade das certidões.', 'alvo', '214 72% 44%', 'Seções 5.1 a 5.7 do Relatório Final, mudanças substanciais propostas no fluxo to-be', 'Plano de ação a partir do redesenho dos fluxos (seção 5)', '["O redesenho dos processos de aquisição de medicamentos partiu de reunião de trabalho realizada em 30/10/2025, com a equipe de consultoria, representantes técnicos da SESA/PR e representantes da SEFA/PR. Nela, os fluxos mapeados foram revisitados para discutir gargalos, oportunidades de racionalização de etapas e riscos associados às aquisições. Desse trabalho resultaram duas categorias de proposições: alterações estruturais no fluxo e recomendações de boas práticas.","Esta recomendação reúne as alterações estruturais, que modificam o encadeamento das atividades dos fluxos redesenhados. São três: a elaboração do Documento de Formalização da Demanda (DFD) antes do Estudo Técnico Preliminar (ETP), nos fluxos de dispensa, inexigibilidade, ata de registro de preços e pregão eletrônico (ação 1.1); a verificação de que todos os itens têm preço cotado, com novo trâmite apenas para os itens sem cotação, nas dispensas e inexigibilidades (ação 1.2); e a verificação da validade das certidões negativas no momento da anexação, com notificação ao fornecedor quando houver irregularidade, nas dispensas, inexigibilidades e atas (ação 1.3).","As duas primeiras alterações são executadas pelo CEMEPAR, com aprovação da DAD/CGOV. A terceira envolve o Setor de Empenhos do FUNSAÚDE e o CEMEPAR. O processo de formalização de contratos não foi objeto de redesenho: no momento do mapeamento, ele já apresentava distribuição adequada das atividades e não estava sob a gestão do CEMEPAR."]'::jsonb, true),
  ('sesa', 'p1', 'r2', 2, 'Aprimoramentos nas etapas do fluxo', 'Aprimoramentos institucionais por fluxo que não alteram de imediato o desenho formal dos processos.', 'ajustes', '40 82% 50%', 'Seções 5.1 a 5.7 do Relatório Final, recomendações e pontos de atenção para aprimoramento institucional', 'Plano de ação a partir do redesenho dos fluxos (seção 5)', '["As recomendações de boas práticas tratam de aprimoramentos institucionais que afetam o desempenho do processo, mas não exigem alteração imediata do fluxo formal representado em BPMN. Como a reunião de redesenho contou sobretudo com o CEMEPAR, parte dessas proposições depende de outras unidades da SESA. Com a consolidação do plano de ação, cada uma passou a ter unidade responsável definida, entre elas a DAD, o Gabinete, o FUNSAÚDE e o NII.","As dez ações se organizam em quatro conjuntos. O primeiro trata dos atos de assinatura e despacho que alongam a tramitação: o momento da assinatura do ETP; a análise do memorando com o despacho de autorização, que hoje leva de 20 a 40 dias; e a consolidação das assinaturas sequenciais do edital nos pregões (ações 2.1 a 2.3). O segundo trata da aquisição por ata de registro de preços: a consulta à disponibilidade da ata antes da abertura do protocolo; a confirmação da exigência da lista nominal de pacientes no saque; e uma alternativa que impeça a tramitação de reajuste de preço quando houver compra em curso (ações 2.4 a 2.6).","O terceiro conjunto trata das importações: a vinculação do envio dos medicamentos à ordem de compra e a avaliação do pagamento por remessa no lugar da carta de crédito (ações 2.7 e 2.8). O quarto trata da entrada de medicamentos: a digitalização do registro de recebimento na CAF e a eliminação das planilhas preenchidas à mão (ações 2.9 e 2.10). A consulta à ata e as melhorias na entrada de medicamentos dependem do apoio de sistema de informação, tema da Recomendação 3."]'::jsonb, true),
  ('sesa', 'p1', 'r3', 3, 'Medidas transversais aos processos de aquisição', 'Medidas que alcançam todos os processos de aquisição.', 'base', '194 85% 38%', 'Seção 5.8 do Relatório Final, Recomendações gerais', 'Plano de ação a partir do redesenho dos fluxos (seção 5)', '["As medidas desta recomendação têm caráter transversal: alcançam todos os processos de aquisição de medicamentos, e não um fluxo específico. Voltam-se ao fortalecimento da governança das compras, à capacidade de planejamento e à previsibilidade da tramitação, com efeitos sobre várias etapas ao mesmo tempo, como a redução de retrabalho e a mitigação de riscos.","A primeira medida é a implantação de um sistema integrado de planejamento de compras (ação 3.1), a cargo do NII, do CEMEPAR e da DAD. O sistema centraliza em base única as informações hoje dispersas: contratos vigentes, atas de registro de preços, estoques, demandas e histórico de consumo. Parte dos gargalos identificados nas análises vem dessa dispersão, como a demora na instrução processual e as paralisações por falta de informação. O sistema também é a base para aprimoramentos da Recomendação 2.","A segunda medida é a uniformização dos critérios de condução, a cargo da DAD e do CEMEPAR: níveis de serviço de referência para as etapas críticas e critérios normatizados para o uso de tarjas de urgência no e-Protocolo (ação 3.2). A terceira é a eliminação da duplicidade de informações entre DFD e ETP, com a revisão dos modelos pela DAD (ação 3.3). Ela complementa a mudança de ordem entre os dois documentos prevista na Recomendação 1."]'::jsonb, true),
  ('sesa', 'p1', 'r4', 4, 'Implantação e acompanhamento das melhorias', 'Fases de implantação: mobilização, validação institucional, backlog e acompanhamento permanente por indicadores.', 'usuarios', '262 60% 52%', 'Seções 8.1 e 8.2 do Relatório Final, plano de implementação em fases', 'Quadro 17. Fases, ações e prazos do plano de implementação', '["O plano de implementação organiza em formato executável as proposições do redesenho: as alterações estruturais e as recomendações de aprimoramento institucional. Como parte delas depende de deliberação de instâncias superiores e de outras unidades, o plano também ordena dependências e pontos de decisão, em fases sucessivas: primeiro os ajustes de rito e os instrumentos de execução; depois os mecanismos de gestão do fluxo; em seguida as soluções estruturantes de dados e sistemas; e, por fim, o acompanhamento permanente.","As três primeiras ações correspondem à mobilização da implantação e ficam a cargo do NPS: designar responsáveis pelas frentes de coordenação, processos, sistemas, indicadores e comunicação (ação 4.1); validar as recomendações com a alta administração, pactuando responsabilidades (ação 4.2); e consolidar um backlog único das ações, classificado por dependência técnica e institucional (ação 4.3).","As duas últimas ações tornam o acompanhamento uma prática permanente de gestão, conduzida pelo CEMEPAR: um rito bimestral de análise crítica dos indicadores, voltado a gargalos e reincidências (ação 4.4), e a condução das ações corretivas, preventivas e de aperfeiçoamento que dele resultarem (ação 4.5).","Prazos indicativos do plano de implementação (Quadro 17 do relatório): mobilização e detalhamento executivo, mês 1; padronização operacional e ajustes de rito, meses 2 e 3; medidas estruturantes com suporte de dados e sistemas, meses 4 a 9; consolidação, acompanhamento e melhoria contínua, a partir do mês 6, em caráter contínuo."]'::jsonb, true),
  ('sesa', 'p1', 'r5', 5, 'Sustentação do painel de indicadores', 'Hospedagem, alimentação automatizada e padronização das bases do painel de indicadores.', 'grafico', '147 67% 37%', 'Seção 8.2 do Relatório Final, Operacionalização e sustentação do painel de indicadores', 'Plano de ação a partir da sustentação do painel (seção 8.2)', '["Os indicadores de desempenho e o painel gerencial de monitoramento foram elaborados no âmbito do estudo. Esta recomendação não trata da construção do painel, mas da sua operação contínua, para que ele deixe de ser um produto pontual e passe a integrar a rotina de gestão do CEMEPAR.","São três frentes: a hospedagem do painel em rede interna da SESA/PR ou do CEMEPAR, sem circulação de arquivos avulsos por e-mail, a cargo do NII (ação 5.1); a rotina automatizada de extração e atualização dos dados, que elimina a carga manual (ação 5.2); e a padronização das colunas e dos campos de origem das bases de licitações e contratações diretas, condição para a automação (ação 5.3). As duas últimas frentes estão a cargo da DAD e do NII. A análise periódica dos indicadores faz parte do rito bimestral previsto na Recomendação 4."]'::jsonb, true),
  ('seed', 'p1', 'r1', 1, 'Potencial de economia por decaimento de quartis na água', 'Economia concentrada em poucas unidades: prioridade às escolas atípicas e ao quarto quartil.', 'gota', '194 85% 38%', 'Seção de Análise e Recomendações do Relatório Final', 'Quadro 5. Governança das ações recomendadas', '["A base de água reúne 1.499 escolas com indicador válido, distribuídas pelos catorze clusters, das quais 34 são classificadas como atípicas. Aplicando a tarifa de referência ao consumo médio mensal de cada escola, a despesa estimada do conjunto é de aproximadamente R$ 5,66 milhões por mês, ou cerca de R$ 67,9 milhões por ano. A simulação de decaimento estima quanto dessa despesa seria evitável caso as escolas de maior consumo fossem trazidas ao patamar de faixas mais eficientes do próprio cluster. Os valores a seguir representam um teto teórico, pois assumem que toda escola de uma faixa atinge integralmente o alvo definido; a economia efetivamente capturável é menor e depende de intervenções caso a caso.","A tabela apresenta um menu de configurações de decaimento, da mais restrita à mais ambiciosa, cada uma com o seu resultado potencial. Todas adotam a mediana da faixa de destino como alvo, salvo indicação contrária. Nas configurações que envolvem as escolas atípicas, considera-se apenas as de consumo alto, situadas acima do limite superior do cluster; as atípicas de consumo muito baixo não geram economia, pois a simulação nunca aumenta o consumo.","A leitura revela uma concentração marcante da economia em poucas escolas. O tratamento exclusivo das unidades atípicas, apenas 22 escolas, já recuperaria 7,8 % da despesa total, e o decaimento do quarto quartil para o terceiro, sozinho, responde por 16,8 %. Combinadas, essas duas frentes alcançam 24,6 % da despesa atuando sobre menos de quatrocentas escolas. Isso indica que, na água, o gasto excedente está fortemente concentrado no topo da distribuição. A escolha da base estatística, média ou mediana, altera muito pouco o resultado, com diferença inferior a meio ponto percentual, o que confirma que a definição do alvo importa menos do que a escolha de quais faixas decaem. No outro extremo, a convergência de todas as faixas à mediana eleva o potencial a 37,8 %, e o cenário-teto, que projeta todas as escolas ao primeiro quartil, chega a 52,2 %, embora envolva intervenção em mais de mil escolas e represente um limite conceitual, não uma meta operacional.","A trajetória recomendada é faseada. A prioridade imediata deve recair sobre as escolas atípicas e o quarto quartil, frente que reúne alto retorno e baixo número de unidades, com potencial da ordem de R$ 16,7 milhões anuais, condicionada à validação caso a caso, já que parte do consumo atípico pode decorrer de vazamentos ou de erros de medição, e não de uso recuperável. O cenário escalonado completo, com potencial em torno de R$ 20,8 milhões anuais, é uma referência adequada de médio prazo, e os cenários de convergência à mediana e de teto de eficiência servem para dimensionar o horizonte máximo de ganho."]'::jsonb, true),
  ('seed', 'p1', 'r2', 2, 'Potencial de economia por decaimento de quartis na energia', 'Economia difusa: estratégia de cobertura ampla do quarto quartil, e não de exceção.', 'raio', '40 82% 50%', 'Seção de Análise e Recomendações do Relatório Final', 'Quadro 5. Governança das ações recomendadas', '["A base de energia reúne 1.879 escolas com indicador válido, das quais 36 são atípicas, e cobre um período mais longo, de 2014 a 2025. A despesa estimada do conjunto, pela tarifa de referência, é de aproximadamente R$ 5,61 milhões por mês, ou cerca de R$ 67,3 milhões por ano. Como a janela histórica é ampla, o indicador médio de cada escola incorpora anos de perfis de consumo distintos, de modo que os valores devem ser lidos como referência de longo prazo; um recorte por anos recentes tenderia a refinar a estimativa. Valem as mesmas ressalvas de teto teórico apontadas na água. Também aqui, nas configurações que envolvem as escolas atípicas, considera-se apenas as de consumo alto; das 36 atípicas, somente 8 decaem, pois as 28 de consumo muito baixo já consomem abaixo do alvo e são examinadas adiante como possível sub-registro.","O contraste com a água é o achado central. Na energia, as escolas atípicas de consumo alto respondem por apenas 0,9 % da despesa, com oito unidades, ou seja, não há ganho expressivo concentrado em poucos casos extremos. A economia é difusa: o grosso do potencial vem do quarto quartil, com 12,7 %, e se acumula de forma mais gradual ao longo das faixas, alcançando 20,4 % no cenário escalonado completo. Em outras palavras, enquanto na água a estratégia eficiente é cirúrgica, focada em poucas escolas de consumo extremo, na energia a redução exige atuação em larga escala, distribuída por centenas de unidades de consumo moderadamente elevado. A base estatística, novamente, quase não altera o resultado.","Para a energia, a estratégia recomendada é de cobertura ampla, e não de exceção. Como o tratamento isolado de atípicas tem efeito desprezível, a prioridade deve ser o quarto quartil, que sozinho responde por cerca de R$ 8,6 milhões anuais de potencial, evoluindo para o cenário escalonado completo, em torno de R$ 13,7 milhões anuais, como meta de médio prazo. A convergência à mediana e o teto de eficiência delimitam o horizonte superior, respectivamente próximos de R$ 18,3 milhões e R$ 30,3 milhões anuais."]'::jsonb, true),
  ('seed', 'p1', 'r3', 3, 'Percepções específicas do consumo de água', 'Oportunidades concentradas, indícios de sub-registro e referências de boa prática.', 'busca', '214 72% 44%', 'Seção de Análise e Recomendações do Relatório Final', 'Quadro 5. Governança das ações recomendadas', '["Oportunidades concentradas em poucas escolas: A análise individualizada confirma que, na água, o gasto excedente está fortemente concentrado em um pequeno número de unidades. As quinze escolas de maior oportunidade, medidas pelo que economizariam caso fossem trazidas à mediana do seu cluster, somam cerca de R$ 494 mil por mês, ou aproximadamente R$ 5,9 milhões por ano. O caso mais extremo é o Colégio Estadual do Campo Cavaco, em Cantagalo (Núcleo de Laranjeiras do Sul), cujo consumo de 60,5 metros cúbicos por aluno ao mês equivale a 181,9 vezes a mediana do seu cluster e representa, sozinho, potencial da ordem de R$ 164 mil por mês, perto de R$ 2 milhões por ano. Um valor dessa magnitude é incompatível com o uso escolar normal e aponta com alta probabilidade para vazamento, ligação com perda ou erro de medição e registro, de modo que a primeira providência não é uma meta de redução, mas uma verificação de campo. Outras unidades de destaque são o Colégio Estadual José Pavan, em Jacarezinho (17,3 vezes a mediana, R$ 39 mil por mês), o Colégio Estadual São João, em Pato Branco (13,3 vezes, R$ 20 mil por mês), e dois centros estaduais de educação profissional com alojamento, em Apucarana e Pinhais, cujo consumo elevado pode ter parcela legítima ligada à atividade agropecuária ou residencial, ainda assim merecendo conferência.","Indícios de sub-registro: No extremo oposto, doze escolas apresentam consumo por aluno extraordinariamente baixo, entre 4 e 19 % da mediana do seu cluster, várias delas de grande porte, como o Colégio de Aplicação da Universidade Estadual de Londrina, com 1.636 alunos e consumo de 0,007 metro cúbico por aluno ao mês, e o CEEBJA Doutor Mário Faraco, em Piraquara, com 3.238 alunos. Valores tão baixos para unidades grandes sugerem sub-registro, abastecimento por fonte própria, como poço artesiano, ou faturamento lançado em outra unidade consumidora, e não eficiência real. Esses casos não representam economia, mas uma fragilidade de dados que recomenda auditoria cadastral, sob risco de subestimar a despesa real da rede.","Referências de boa prática: A base também evidencia que porte elevado não impede alta eficiência. Em todos os clusters de maior tamanho há escolas grandes operando bem abaixo da mediana do grupo, como o Colégio Estadual Frederico Guilherme Giese, em Piên, com 1.057 alunos a 37 % da mediana, e o Colégio Estadual do Paraná, em Curitiba, com 3.420 alunos a 38 % da mediana. Essas unidades servem de referência concreta de boa prática para escolas de perfil semelhante, e o seu exame qualitativo, quanto a manutenção hidráulica, presença de medição própria e rotinas de uso, pode subsidiar a difusão de práticas eficientes.","Onde a comparação rende mais: O cluster de escolas pequenas de jornada parcial é o mais heterogêneo, com o terceiro quartil quase três vezes maior que o primeiro, o que indica grande espaço de aproximação interna. É também nesse grupo que se encontram os exemplos de maior e de menor eficiência, o que o torna prioritário para ações de nivelamento."]'::jsonb, true),
  ('seed', 'p1', 'r4', 4, 'Percepções específicas do consumo de energia', 'Oportunidade difusa e forte incidência de consumo implausivelmente baixo.', 'busca', '262 60% 52%', 'Seção de Análise e Recomendações do Relatório Final', 'Quadro 5. Governança das ações recomendadas', '["Oportunidade difusa, e não concentrada: Ao contrário da água, na energia não há ganho expressivo concentrado em poucos casos extremos. As quinze escolas de maior oportunidade somam apenas cerca de R$ 120 mil por mês, ou aproximadamente R$ 1,4 milhão por ano, e a maior delas, o Colégio Estadual São Pedro e São Paulo, em Campo Largo, responde por R$ 18 mil por mês. O traço marcante é que as maiores oportunidades não são escolas atípicas, mas grandes unidades consumindo de duas a três vezes a mediana do seu cluster, com destaque para diversas super escolas e grandes escolas com mais de mil e quinhentos alunos e oferta de ensino médio noturno, como os colégios Castelo Branco, em Toledo, e o Instituto de Educação de Maringá. Isso indica que, na energia, a redução exige atuação de cobertura ampla sobre o conjunto do quarto quartil, provavelmente associada a climatização, iluminação e uso das instalações em período noturno, e não uma intervenção cirúrgica em poucos endereços.","Indícios de sub-registro. O ponto de atenção mais relevante na energia é a quantidade de consumo implausivelmente baixo: vinte e oito escolas figuram como atípicas por baixo, várias de grande porte, como o Colégio Estadual Rui Barbosa, em Jacarezinho, com 1.088 alunos e consumo de 0,046 quilowatt-hora por aluno ao mês, e o Colégio Estadual Doutor Gastão Vidigal, em Maringá, com 2.709 alunos. Consumo próximo de zero em escolas desse tamanho é incompatível com o funcionamento regular e sugere sub-registro, geração própria, como energia solar, ou faturamento em unidade consumidora distinta. Recomenda-se auditoria de medição e cadastro dessas unidades, pois a sua ausência distorce as estatísticas dos clusters e pode mascarar despesa relevante.","Referências de boa prática. Também na energia há grandes escolas muito eficientes, operando entre 22 e 54 % da mediana do seu cluster, como o Colégio Estadual João Hoinatz de Andrade, em Fazenda Rio Grande, com 960 alunos a 24 % da mediana. Tais unidades, por terem porte comparável às de maior consumo, são as referências mais úteis para orientar intervenções em climatização e eficiência elétrica nas escolas do quarto quartil.","Onde a comparação rende mais. Os clusters de escolas pequenas de jornada parcial e de escolas micro são os mais heterogêneos, o que sugere que parte da dispersão decorre de diferenças de infraestrutura e de hábitos de uso passíveis de nivelamento, mais do que de necessidades intrínsecas distintas."]'::jsonb, true),
  ('seed', 'p1', 'r5', 5, 'Otimização dos recursos', 'Critérios objetivos de priorização por cluster, indicador de gasto por aluno e difusão de boas práticas.', 'alvo', '147 67% 37%', 'Seção de Análise e Recomendações do Relatório Final', 'Quadro 5. Governança das ações recomendadas', '["As análises das subseções anteriores quantificaram o potencial de racionalização das despesas com água e com energia elétrica da Rede Pública Estadual de Ensino e identificaram onde o gasto se afasta do padrão esperado entre unidades comparáveis. Esta subseção converte esses achados em recomendações orçamentárias acionáveis, organizadas em duas dimensões complementares: a elaboração da peça orçamentária, ou seja, como a peça dos próximos ciclos pode refletir, ao longo do tempo, a economia comprovada com os ganhos de eficiência, e a execução orçamentária, isto é, como aplicar e acompanhar o recurso já dotado para gerar mais resultado por real investido. As recomendações decorrem da aplicação da Gestão Matricial de Despesas (GMD), ferramenta do modelo de Orçamento para Resultados (OpR) selecionada para o estudo, que confronta os pacotes de despesa de água e energia com as unidades que os executam e prioriza a redução do gasto a partir da comparação entre escolas semelhantes. Cabe registrar que o valor das recomendações não se reduz a ampliar ou a cortar a dotação, mas a qualificar a alocação, atendendo mais com o mesmo recurso, condicionando a aplicação ao desempenho e direcionando o esforço para as unidades de maior potencial.","A otimização parte de um princípio central das análises: elevar o resultado por real investido não exige ampliação da dotação, mas a aplicação de critérios objetivos de priorização derivados do padrão de consumo de cada agrupamento. O acompanhamento das unidades apoia-se em um indicador único e comparável, o gasto por aluno por mês de cada escola, derivado do consumo físico e da tarifa de referência e sempre lido frente ao seu próprio cluster, conforme a lógica da Gestão Matricial de Despesas. Adota-se como prática de eficiência que o ideal de cada escola é convergir para o consumo mediano do cluster em que se insere; a mediana do cluster é, assim, o marco de eficiência, o patamar de referência que uma unidade de determinado porte e regime deveria alcançar, e para o qual as ações de racionalização buscam levar as escolas de gasto excedente.","O esforço sistemático concentra-se no quarto quartil de cada cluster, os vinte e cinco por cento de maior gasto por aluno de cada grupo, sobre os quais se aplica a lógica de redução em larga escala. Assumindo inicialmente, como método, a sugestão apresentada na análise de levar o quarto quartil ao patamar mediano do terceiro quartil, obtém-se um primeiro passo, conservador, no caminho da eficiência. Esse passo não esgota o objetivo: a convergência ao consumo mediano do próprio cluster é o horizonte de referência, alcançado de forma faseada à medida que cada faixa avança em direção à mediana, tendo o primeiro quartil como teto de eficiência.","As escolas atípicas, situadas fora dos limites estatísticos do cluster, não entram na estimativa de redução financeira sistemática: por serem casos isolados, recebem análise particular, voltada a compreender a razão da dispersão antes de qualquer meta, e o eventual ganho só é incorporado depois desse estudo. As atípicas de consumo muito alto exigem verificação de campo individual, pois o consumo extremo costuma indicar vazamento, perda ou erro de medição, e não uso recuperável; na água, ainda que isoladas, algumas dessas unidades carregam valor material relevante, como a de maior consumo, com mais de cento e oitenta vezes a mediana do seu cluster. As atípicas de consumo muito baixo sinalizam provável sub-registro, abastecimento ou geração por fonte própria ou faturamento lançado em outra unidade, e demandam auditoria cadastral e de medição.","O quadro a seguir resume, para cada agrupamento e cada recurso, o consumo mediano por aluno, adotado como marco de eficiência, e o número de escolas situadas no quarto quartil, sobre as quais recai o esforço sistemático. A leitura mostra que a aplicabilidade do método depende do tamanho do cluster. Nos agrupamentos numerosos, a partição em quartis é nítida e o quarto quartil reúne dezenas de unidades; nos menores, sobretudo os de alojamento, com três a seis escolas, os quartis tornam-se imprecisos e algumas faixas chegam a ficar vazias, de modo que o decaimento sistemático não encontra faixa de destino para essas poucas unidades. É o caso dos clusters de alojamento de menor porte, em que não há terceiro quartil ao qual aproximar o quarto. Por essa razão, das 368 escolas de quarto quartil na água e das 463 na energia, o primeiro passo do método alcança efetivamente 367 e 461, respectivamente, permanecendo as demais para análise caso a caso, ao lado das unidades atípicas.","Considerado o ganho sistemático, excluídas as atípicas, o potencial é de magnitude comparável nos dois recursos. No primeiro passo do método, levar o quarto quartil ao patamar mediano do terceiro quartil, estima-se da ordem de R$ 11,4 milhões anuais na água, sobre cerca de 367 escolas, e de R$ 8,6 milhões anuais na energia, sobre cerca de 461 escolas. A distinção entre os dois recursos não está nesse ganho sistemático, e sim na forma do restante da distribuição, tratado à parte. Na água, além do quarto quartil, existe um grupo reduzido de unidades atípicas de consumo muito alto, cerca de vinte, que concentram valor expressivo e constituem uma frente adicional, examinada caso a caso e fora da estimativa acima. Na energia, praticamente não há casos extremos, de modo que todo o potencial se encontra no próprio quarto quartil, sem essa frente concentrada, com atenção às grandes unidades de oferta noturna, em que o consumo se associa a climatização, iluminação e uso estendido das instalações. À medida que as faixas avançam em direção à mediana do cluster, o potencial sistemático se amplia, alcançando a ordem de R$ 20,8 milhões anuais na água e de R$ 13,7 milhões na energia na redução escalonada do conjunto das faixas."]'::jsonb, true),
  ('seil', 'p1', 'r1', 1, 'Operacionalização do monitoramento contínuo', 'Comissão de M&A, fluxos de apuração dos cinco indicadores, relatórios técnicos de monitoramento e padronização dos relatórios da AMP.', 'grafico', '214 72% 44%', 'Seção 4.2 do Relatório Final, Próximos passos', 'Quadro 8. Plano de Ação', '["A sistemática de monitoramento e avaliação do Programa Construindo o Paraná Digital foi estruturada para viabilizar o acompanhamento contínuo do desempenho ao longo dos quatro anos de implementação e, complementarmente, para permitir a continuidade da avaliação da efetividade do programa ao seu término. A sistemática é apoiada nos cinco indicadores de monitoramento contínuo detalhados na seção anterior, sendo quatro voltados às dimensões de eficácia e eficiência e um quinto (a Taxa de celebração de convênios) voltado à dimensão de efetividade, apurado semestralmente a partir do penúltimo ano do Programa e ao longo dos dois anos subsequentes ao seu encerramento.","Os Relatórios Técnicos de Monitoramento deverão conter, sem prejuízo de outros elementos: descrição sumária das atividades desenvolvidas e das metas estabelecidas; análise das atividades realizadas, do cumprimento das metas e dos resultados obtidos com base nos indicadores definidos; valores efetivamente transferidos pela Administração Pública Estadual; e documentos comprobatórios das despesas realizadas. Caso seja identificada pelo Gestor SEIL a necessidade de ajuste ou complementação do relatório, o Gestor da AMP deverá atender às solicitações ou apresentar justificativa no prazo de até dez dias corridos.","As Reuniões de Aprendizado Estratégico têm por finalidade criar um espaço institucionalizado para análise coletiva dos resultados dos indicadores, discussão de hipóteses sobre fatores que influenciam o desempenho observado e deliberação sobre eventuais ajustes de rota na execução do programa. Essas reuniões não substituem os ritos de monitoramento operacional, mas os complementam ao incorporar uma dimensão reflexiva e estratégica ao ciclo de M&amp;A."]'::jsonb, true),
  ('seti', 'p1', 'r1', 1, 'Consolidação e governança de dados', 'Responsáveis por base, protocolo mínimo de governança da informação, tratamento das bases incompletas e ampliação da série histórica.', 'base', '214 72% 44%', 'Seção 4.2.1 do Relatório Final e Bloco 1 dos Próximos passos', 'Quadro 8. Plano de ação preliminar para consolidação e governança de dados', '["Recomenda-se, no curto prazo, a institucionalização do processo de atualização do Painel de Indicadores das Universidades Estaduais do Paraná, com a definição formal dos responsáveis por cada uma das bases utilizadas, dos prazos de disponibilização e dos procedimentos de validação das informações.","A periodicidade de atualização deve observar a natureza e o ciclo de produção de cada fonte. Para as bases de execução orçamentária, corpo docente e demais informações administrativas, recomenda-se atualização mensal ou trimestral, conforme a disponibilidade dos sistemas de origem. Para as bases nacionais do Censo da Educação Superior, CAPES, CNPq e demais fontes oficiais, a atualização deverá acompanhar o calendário anual de divulgação dos dados.","Também se recomenda a adoção de um protocolo mínimo de governança da informação, contemplando: identificação do responsável pela extração e disponibilização de cada base; definição da periodicidade de atualização; registro da data de referência e da data de extração; verificação da integridade, cobertura e consistência dos dados; documentação de alterações metodológicas; manutenção de um histórico das versões das bases e dos indicadores.","As lacunas identificadas em fontes específicas devem ser objeto de tratamento progressivo. Entre elas, destacam-se os dados de suplementação, as informações de egressos obtidas por meio do cruzamento entre bases acadêmicas e a RAIS/CBO e os indicadores relacionados à pesquisa, extensão, inovação e impacto regional, cuja incorporação depende da existência de bases estruturadas e comparáveis por instituição. Em relação ao eixo de Pesquisa, especificamente, destaca-se o programa UniData, em fase de idealização pela SETI, que deverá consolidar esses dados e viabilizar sua futura incorporação ao painel.","Recomenda-se, ainda, a ampliação gradual da janela histórica das informações orçamentárias e acadêmicas. A consolidação de séries mais longas permitirá analisar tendências, distinguir oscilações pontuais de mudanças estruturais e, futuramente, responder de forma mais robusta à pergunta sobre a evolução da relação entre recursos e desempenho ao longo do tempo."]'::jsonb, true),
  ('seti', 'p1', 'r2', 2, 'Institucionalização do uso do painel na gestão orçamentária', 'Painel como instrumento permanente do ciclo orçamentário e leitura compartilhada com as IEES.', 'grafico', '194 85% 38%', 'Seção 4.2.2 do Relatório Final e Bloco 2 dos Próximos passos', 'Quadro 9. Plano de ação preliminar para institucionalização do uso do painel na gestão orçamentária', '["Recomenda-se que a SETI incorpore o painel como instrumento permanente de monitoramento e apoio à tomada de decisão, utilizando-o em diferentes momentos do ciclo de gestão das universidades estaduais.","No processo de planejamento orçamentário, o painel poderá subsidiar a leitura das necessidades institucionais, complementando as informações históricas de execução com evidências relacionadas ao porte, à oferta acadêmica, à dispersão territorial, à estrutura docente, aos resultados acadêmicos e à dinâmica orçamentária de cada universidade.","Contudo, os índices e rankings produzidos pela ferramenta não devem ser utilizados, de forma isolada ou automática, como critério de redução, ampliação ou redistribuição de recursos. Sua principal função é identificar padrões, divergências e situações que demandem aprofundamento, permitindo que as decisões orçamentárias sejam apoiadas por evidências mais qualificadas e por análises complementares.","Nesse sentido, recomenda-se que os resultados do painel sejam utilizados para: apoiar a elaboração da proposta orçamentária anual das IEES; identificar instituições, dimensões ou indicadores que demandem análise adicional; contextualizar solicitações de ampliação de recursos; acompanhar a evolução dos indicadores institucionais; orientar a formulação de metas e compromissos de melhoria; subsidiar avaliações específicas sobre temas identificados como prioritários; apoiar discussões sobre expansão de cursos, vagas, quadro docente e infraestrutura.","Recomenda-se também a realização de reuniões periódicas de análise compartilhada entre a SETI e as sete IEES, com participação da SEFA quando pertinente. Esses encontros podem ser organizados por dimensão temática, como acesso e oferta, permanência, pós-graduação, corpo docente, egressos e execução orçamentária, transformando o painel em instrumento de diálogo técnico e não apenas em repositório de informações.","A utilização do painel deve estimular a identificação de boas práticas e o aprendizado entre as instituições. Universidades que apresentem resultados favoráveis em determinadas dimensões podem servir como referência para o aprofundamento qualitativo dos fatores associados ao desempenho, respeitadas as diferenças de contexto e de missão institucional."]'::jsonb, true),
  ('seti', 'p1', 'r3', 3, 'Aprofundamento analítico', 'Perguntas do estudo que dependem de novas bases: composição da despesa e eficiência, atividades-fim, série histórica e Índice de Desempenho da Formação.', 'busca', '262 60% 52%', 'Bloco 3 dos Próximos passos do Relatório Final, a partir da Síntese dos achados', 'Quadro 10. Plano de ação preliminar para aprofundamento analítico', '["No que se refere ao desempenho físico-financeiro, o painel demonstrou que existe associação positiva entre o volume de recursos aplicados e os resultados acadêmicos, porém essa relação não é linear nem suficiente para explicar, isoladamente, o desempenho das instituições. A existência de universidades que apresentam resultados semelhantes, mesmo operando com diferentes níveis de gasto por aluno, evidencia que fatores relacionados à organização institucional, à composição da oferta acadêmica, à estrutura docente, à capilaridade territorial e às características da própria universidade também influenciam os resultados observados. Embora essas evidências não permitam estabelecer relações de causalidade, elas constituem importantes subsídios para orientar investigações mais aprofundadas e apoiar futuras decisões de gestão.","Sob a perspectiva da governança da informação, o estudo evidenciou que a principal limitação para o monitoramento do sistema universitário não está na inexistência de dados, mas na fragmentação das informações entre múltiplas bases, produzidas por diferentes instituições, com periodicidades, metodologias e formatos distintos. O Painel de Indicadores das Universidades Estaduais do Paraná representa, nesse contexto, um avanço significativo ao integrar essas informações em uma plataforma única, permitindo consultas, comparações e análises que anteriormente demandavam elevado esforço de consolidação manual.","O conjunto de ações propostas constitui uma agenda de trabalho que combina intervenções de governança de dados, uso institucional do painel e aprofundamento analítico das questões que orientaram o estudo desde sua etapa inicial. O estudo da SETI encontra-se na transição entre a validação do instrumento de gestão e a pactuação formal de seus próximos passos, o que reforça a relevância de uma reunião dedicada com a Secretaria para validar as ações aqui propostas e orientar sua implementação."]'::jsonb, true),
  ('der', 'p1', 'r1', 1, 'Consolidação do painel e da base de indicadores', 'Governança e atualização do painel, série histórica da malha, base de execução por contrato, dados de tráfego e leitura por rodovia.', 'base', '214 72% 44%', 'Seção 4.2.1 e Bloco 1 dos Próximos passos', 'Plano de ação preliminar, Bloco 1: Consolidação de dados', '["Recomenda-se instituir um processo formal de atualização e governança do painel, com definição dos responsáveis técnicos por cada base utilizada, periodicidade e data de corte, procedimentos de validação, regras de versionamento e registro das alterações realizadas. O processo deverá abranger a base de contratos DOPSR1 por regional, a condição da malha, os indicadores IRI/FWD e as demais fontes que venham a ser incorporadas. Recomenda-se, ainda, priorizar o tratamento das lacunas identificadas na seção 3.5, em especial a ampliação da série histórica de condição da malha e a construção de uma base de execução por contrato com meta física, o que permitirá, no futuro, avançar de uma leitura transversal para uma leitura de evolução ao longo do tempo.","Recomenda-se, adicionalmente, evoluir a granularidade das informações exibidas no painel, atualmente consolidadas por Superintendência Regional. Em particular, recomenda-se que o mapa exploratório da malha seja estratificado por rodovia, e não apenas por SR, de modo a permitir a identificação de trechos específicos que demandem atenção técnica, e não apenas regionais inteiras. Da mesma forma, os demais indicadores do painel (execução financeira, tipo de intervenção contratual e condição da malha) devem ser segmentados no maior nível de desagregação que a base de dados permitir, uma vez que decisões gerenciais mais tempestivas e específicas dependem de leituras territoriais mais finas do que a média regional agregada."]'::jsonb, true),
  ('der', 'p1', 'r2', 2, 'Institucionalização do uso do painel na gestão orçamentária', 'Painel como instrumento permanente de monitoramento, leitura compartilhada entre diretorias e regionais e uso no ciclo orçamentário.', 'grafico', '194 85% 38%', 'Seção 4.2.2 e Bloco 2 dos Próximos passos', 'Plano de ação preliminar, Bloco 2: Institucionalização do uso do painel', '["Recomenda-se que o DER incorpore o painel como instrumento permanente de monitoramento, e não como critério automático de corte ou redistribuição de recursos entre regionais. Os indicadores de aderência alocativa e de pressão futura devem ser utilizados para: identificar SRs ou contratos que demandem análise técnica adicional antes de decisões orçamentárias; contextualizar solicitações de ampliação de recursos por regional, à luz do tipo de serviço e da criticidade técnica, e não apenas do valor histórico executado; acompanhar a evolução da participação de contratos emergenciais como sinal antecedente de risco; subsidiar reuniões periódicas entre a Diretoria Técnica, a Diretoria de Operação e as Superintendências Regionais para leitura conjunta dos indicadores do painel."]'::jsonb, true),
  ('der', 'p1', 'r3', 3, 'Aprofundamento analítico', 'Rastreabilidade municipal do gasto, tipologia de serviço e pavimento e contratos emergenciais como sinal de pressão futura.', 'busca', '262 60% 52%', 'Bloco 3 dos Próximos passos, a partir da Síntese dos achados e da seção 3.5', 'Plano de ação preliminar, Bloco 3: Aprofundamento analítico', '["A Ação 8398 apresentou elevada execução orçamentária em 2025, com 99,79% do valor disponível empenhado e 91,96% liquidado (dados do DEFF 2025, referentes apenas à Ação 8398). A análise de aderência, contudo, concentrou-se nos 46 contratos de manutenção e conservação de pavimentos, responsáveis por aproximadamente 72,8% do total liquidado da ação. Nesse recorte, o valor liquidado por quilômetro não apresentou associação linear com a condição observada da malha. O achado não permite inferir eficiência relativa entre as regionais nem atribuir efeitos causais ao gasto, mas demonstra que as decisões orçamentárias devem combinar informações financeiras com dados de criticidade técnica, tipo de serviço, perfil de tráfego e histórico do pavimento.","Contratos emergenciais como sinal de pressão não planejada. A maior participação de contratos emergenciais, especialmente na SR Noroeste, deve ser tratada como um sinal exploratório de pressão não planejada. Esse padrão pode refletir demandas corretivas em trechos sem cobertura contratual regular, mas a hipótese de déficit acumulado de manutenção preventiva deverá ser confirmada por meio da análise do histórico dos contratos, da condição anterior dos segmentos e das causas que motivaram cada contratação emergencial.","Rastreabilidade municipal do gasto (linha de investigação descontinuada). A análise em nível municipal conduzida na fase de diagnóstico, que identificou Reserva e Agudos do Sul como municípios vulneráveis e estratégicos sem valor liquidado identificável na base agregada, não teve continuidade no escopo final do estudo, pois a base financeira não desagrega o gasto por município. As hipóteses levantadas (trechos concessionados, obras vinculadas a outras ações orçamentárias, ou ausência de segregação municipal na gestão contratual) permanecem sem confirmação. Recomenda-se avaliar a inclusão, nos sistemas de gestão contratual SIDER e SIGEF, de campos padronizados de localização por trecho rodoviário e município, quando tecnicamente aplicável, nos novos contratos e aditivos. Essa informação permitirá ampliar a rastreabilidade territorial dos gastos sem desconsiderar que parte dos contratos é executada e gerida em escala regional ou estadual.","O conjunto de ações propostas constitui uma agenda de trabalho que combina consolidação de dados, uso institucional do painel e aprofundamento analítico das questões que orientaram o estudo desde sua etapa inicial."]'::jsonb, true),
  ('sedef', 'p1', 'r1', 1, 'Estruturação, integração e disponibilização das informações das parcerias', 'Conjunto mínimo de dados por proposta, página central das parcerias e integração progressiva das bases.', 'base', '214 72% 44%', '', 'Plano de ação a partir das recomendações do estudo', '["O estudo evidenciou que uma das principais oportunidades de aprimoramento no acompanhamento das parcerias com Organizações da Sociedade Civil está relacionada à forma como as informações são registradas, organizadas e disponibilizadas ao longo do ciclo dos chamamentos. Embora a SEDEF produza e mantenha diferentes registros sobre as propostas e parcerias, essas informações encontram-se distribuídas entre bases administrativas, SISTAG, planos de trabalho, documentos publicados em PDF e páginas do sítio eletrônico da Secretaria, o que dificulta sua utilização integrada para fins de monitoramento, análise e transparência.","Essa limitação ficou evidente durante a análise do Edital nº 005/2024. As bases disponibilizadas permitiram acompanhar informações como identificação das propostas, município, eixo temático, pontuação e valores pagos, mas não reuniam, de forma estruturada e consolidada por projeto, dados sobre beneficiários, metas, entregas realizadas, resultados alcançados e datas intermediárias de tramitação. Parte dessas informações está registrada em documentos individuais, como os planos de trabalho, o que restringe sua utilização em análises agregadas e comparativas.","Recomenda-se, portanto, que a SEDEF defina, para os próximos chamamentos, um conjunto mínimo de informações a serem registradas de forma estruturada para cada proposta ao longo de todo o ciclo da parceria. Esse conjunto pode contemplar, entre outros elementos, identificação da OSC e do projeto; município e eixo de atuação; valores solicitado, aprovado e pago; público previsto e efetivamente atendido; metas e entregas previstas e realizadas; datas das principais etapas de tramitação; situação da execução; e resultados alcançados. A definição prévia desses campos deve considerar as especificidades de cada edital e as informações necessárias ao seu acompanhamento.","A estruturação dessas informações ampliaria a capacidade de monitoramento da própria SEDEF e permitiria desenvolver indicadores que não puderam ser mensurados no estudo. Com o registro individualizado das datas, por exemplo, seria possível calcular o tempo médio de tramitação das propostas e identificar as etapas que concentram maior permanência. Da mesma forma, a consolidação de informações sobre público atendido, metas e entregas permitiria avançar para análises de custo por beneficiário, custo por entrega, cumprimento de metas e relação entre recursos transferidos e resultados produzidos.","Além da estruturação dos dados para uso gerencial, recomenda-se aprimorar sua organização e disponibilização para consulta. Atualmente, informações sobre chamamentos, resultados, cronogramas e execução encontram-se distribuídas em diferentes ambientes e documentos. Como primeiro movimento, a SEDEF pode estruturar uma página específica em seu sítio eletrônico que funcione como ponto central de acesso às informações sobre as parcerias, reunindo, de forma organizada, os editais, cronogramas, resultados das etapas, organizações contempladas, valores transferidos e demais informações de acompanhamento disponíveis.","A experiência do Portal de Parcerias Sociais do Estado de São Paulo, analisada como referência durante o estudo, demonstra uma possibilidade de organização integrada dessas informações. Para a SEDEF, entretanto, a recomendação não pressupõe a implantação imediata de uma nova plataforma tecnológica. A centralização pode ocorrer de maneira progressiva, inicialmente com a reorganização e padronização das informações já produzidas pela Secretaria e, posteriormente, conforme a necessidade e a viabilidade técnica, com maior integração entre os sistemas e bases utilizados na gestão das parcerias.","A medida contribuiria simultaneamente para a gestão interna e para a transparência das parcerias. Para as equipes da SEDEF, reduziria o esforço necessário para reunir e reconstruir informações a cada novo ciclo de acompanhamento e favoreceria análises comparativas entre projetos, eixos e editais. Para OSCs, conselhos e cidadãos, facilitaria a consulta às informações sobre os chamamentos, os recursos transferidos e o andamento das parcerias.","A estruturação e integração dos dados constitui, ainda, uma condição para o aprofundamento futuro da aplicação do Orçamento para Resultados aos instrumentos de transferência de recursos. A disponibilidade de informações estruturadas sobre recursos, público atendido, entregas e resultados permitirá que futuros estudos avancem da análise da seleção e da execução financeira para uma avaliação mais completa sobre o que é entregue com os recursos transferidos e quais resultados são produzidos pelas parcerias financiadas.","O que muda no processo: Organiza dados mínimos por proposta, integra informações hoje dispersas e amplia a capacidade de acompanhar beneficiários, metas, entregas, resultados e etapas de tramitação. Também favorece a transparência das parcerias. Complexidade de implementação: média, exige definição de campos, padronização de registros e eventual integração entre bases e sistemas. Horizonte sugerido: curto a médio prazo."]'::jsonb, true),
  ('sedef', 'p1', 'r2', 2, 'Cadastro único pré-validado para OSCs parceiras', 'Aproveitamento de documentos institucionais já validados, a partir do mapeamento dos documentos exigidos com frequência.', 'arquivo', '40 82% 50%', '', 'Plano de ação a partir das recomendações do estudo', '["A análise do Edital nº 005/2024 evidenciou a recorrência de uma mesma Organização da Sociedade Civil em diferentes propostas. Entre as propostas aptas, foram identificadas 694 OSCs distintas, das quais 308, equivalentes a 44,4%, apresentaram mais de uma proposta. Entre as propostas pagas até maio de 2026, as 315 propostas estavam vinculadas a 220 OSCs, sendo que 71 organizações, ou 32,3%, possuíam mais de um projeto contemplado.","Esse cenário indica que uma parcela relevante das organizações participa simultaneamente de mais de uma proposta dentro do próprio chamamento e pode também participar de outros editais promovidos pela Secretaria. Como as etapas de habilitação e celebração das parcerias envolvem a apresentação e a verificação de documentos relativos à própria organização, parte desse conjunto documental tende a ser exigida reiteradamente ao longo dos diferentes processos.","A oportunidade de simplificação também deve ser considerada à luz do cronograma do Edital nº 005/2024, que prevê 30 dias para a etapa de verificação do cumprimento dos requisitos para celebração do Termo de Fomento. Embora os dados disponíveis não permitam mensurar quanto desse período está associado especificamente à conferência documental, a recorrência de uma mesma OSC em diferentes propostas indica espaço para avaliar o aproveitamento de documentos previamente validados.","Recomenda-se, nesse contexto, que a SEDEF avalie a implantação de um cadastro único pré-validado para OSCs parceiras, com período de validade definido e procedimentos para atualização das informações. A proposta consiste em permitir que documentos institucionais já apresentados, verificados e ainda válidos possam ser aproveitados em diferentes propostas ou chamamentos, preservando a necessidade de apresentação dos documentos específicos de cada projeto e das verificações exigidas no momento da celebração da parceria.","A medida pode reduzir a repetição de atividades tanto para as organizações quanto para as equipes responsáveis pela análise documental. Para as OSCs, diminuiria a necessidade de reunir e encaminhar reiteradamente documentos institucionais já apresentados à Administração. Para a SEDEF, poderia reduzir o esforço de conferência de informações previamente validadas e permitir maior concentração das análises nos requisitos específicos de cada proposta e parceria.","Como referência, o Cadastro Único das Entidades Parceiras do Terceiro Setor (CENTS), do Município de São Paulo, adota mecanismo de cadastramento das entidades parceiras que pode subsidiar a avaliação de alternativas aplicáveis ao contexto da SEDEF. Essa experiência deve ser considerada como referência, e não como modelo a ser reproduzido integralmente, uma vez que eventual solução no Paraná deverá observar o marco normativo estadual, os sistemas utilizados pela Secretaria e os requisitos documentais aplicáveis às diferentes modalidades de parceria.","A implementação da recomendação exige, portanto, uma avaliação prévia sobre quais documentos podem ser reutilizados, por quanto tempo permanecem válidos, quais informações precisam ser atualizadas a cada chamamento e quais verificações devem continuar ocorrendo individualmente por proposta. Também é recomendável avaliar, antes da criação de uma nova solução, em que medida funcionalidades já existentes no SISTAG podem ser ajustadas ou aproveitadas para esse fim.","Como encaminhamento inicial, a SEDEF pode mapear os documentos exigidos de forma recorrente em seus diferentes editais e identificar aqueles cuja conferência poderia ser aproveitada durante determinado período. A partir desse diagnóstico, poderá ser definida a alternativa mais adequada, que pode variar desde ajustes nos procedimentos internos e no SISTAG até, caso se mostre necessário e viável, a implantação de mecanismo específico de cadastro pré-validado.","A recomendação busca, assim, reduzir redundâncias documentais e simplificar o processo de habilitação e celebração das parcerias, especialmente em um contexto no qual uma mesma OSC pode apresentar e executar múltiplos projetos financiados pela SEDEF.","O que muda no processo: Reduz a reapresentação e a conferência repetida de documentos institucionais, simplificando etapas de habilitação e celebração das parcerias. Complexidade de implementação: média, requer avaliação jurídica, definição de validade documental e possíveis ajustes no SISTAG. Horizonte sugerido: médio prazo."]'::jsonb, true),
  ('sedef', 'p1', 'r3', 3, 'Aprimoramento das orientações e dos documentos disponibilizados às OSCs', 'Modelos editáveis, pacote de orientação ao proponente e referencial operacional das parcerias.', 'doc', '147 67% 37%', '', 'Plano de ação a partir das recomendações do estudo', '["Recomenda-se que a SEDEF estruture um conjunto permanente de materiais de orientação destinado às OSCs interessadas em participar de seus chamamentos públicos, abrangendo tanto orientações para elaboração das propostas quanto os documentos necessários ao longo das etapas de seleção e celebração das parcerias. A medida busca facilitar a compreensão das regras dos editais e reduzir dificuldades operacionais enfrentadas pelas organizações durante a preparação e submissão dos projetos.","No Edital nº 005/2024, documentos como declarações, modelo de plano de trabalho e minuta do Termo de Fomento são disponibilizados como anexos incorporados ao próprio arquivo do edital. Para utilizá-los, as organizações precisam localizar os modelos no documento e adaptá-los para preenchimento. A disponibilização desses materiais separadamente, em formatos editáveis e devidamente identificados, constitui uma medida de baixa complexidade que pode facilitar a preparação das propostas e reduzir erros de preenchimento ou formatação.","Recomenda-se, nesse sentido, a criação de um repositório de modelos editáveis, organizado por chamamento e etapa do processo, contendo os documentos necessários à participação das OSCs. Os arquivos podem ser disponibilizados, conforme sua natureza, em formatos como .docx ou PDF preenchível, acompanhados de orientações objetivas sobre sua finalidade e forma de preenchimento.","Além dos modelos, recomenda-se desenvolver um pacote de orientação ao proponente, que pode reunir guia de participação, perguntas frequentes, orientações para elaboração do plano de trabalho, explicações sobre os critérios de avaliação e informações sobre as principais etapas posteriores à seleção. O conteúdo pode ser construído progressivamente, iniciando-se por materiais escritos e, conforme a demanda e a capacidade da Secretaria, incorporando outros formatos, como tutoriais e vídeos explicativos.","A elaboração desses materiais deve considerar as situações observadas nos próprios chamamentos da SEDEF. Informações sobre motivos recorrentes de não avanço das propostas, dúvidas encaminhadas pelas organizações e dificuldades identificadas pelas equipes responsáveis pela análise podem ser utilizadas para atualizar periodicamente as orientações. Dessa forma, os materiais deixam de funcionar apenas como explicação geral do edital e passam a responder a dificuldades efetivamente observadas durante sua execução.","Em perspectiva mais ampla, recomenda-se também avançar na consolidação de um referencial operacional para as parcerias com OSCs, abrangendo as diferentes etapas do ciclo, desde o planejamento e a seleção até a execução, o monitoramento e a prestação de contas. Atualmente, o Estado dispõe do Decreto Estadual nº 3.513/2016, atualizado pelo Decreto nº 7.578/2024, que estabelece o marco jurídico aplicável às parcerias, mas a existência da regulamentação pode ser complementada por orientações operacionais que traduzam seus procedimentos para gestores e organizações parceiras.","Como referência para essa construção, pode ser considerado o Manual MROSC: Do Planejamento à Prestação de Contas, publicado pelo Governo Federal em 2025. Em um primeiro momento, a SEDEF pode utilizar esse material como referência complementar para suas equipes e OSCs parceiras, observadas as especificidades da regulamentação estadual. Em etapa posterior, poderá avaliar a conveniência de elaborar orientações próprias, adaptadas aos procedimentos da Secretaria, ao SISTAG e às características dos chamamentos realizados no Paraná.","A recomendação pode, portanto, ser implementada de maneira gradual, começando por medidas de menor complexidade (como a disponibilização separada dos modelos editáveis e a organização de perguntas frequentes) e avançando para a elaboração de materiais de orientação mais abrangentes à medida que sejam identificadas as necessidades das equipes e das organizações participantes.","O que muda no processo: Facilita a elaboração das propostas e o cumprimento das exigências do chamamento, por meio de guias, perguntas frequentes, modelos editáveis e referências operacionais. Complexidade de implementação: baixa a média, pode começar com materiais escritos e evoluir para conteúdos mais estruturados. Horizonte sugerido: curto a médio prazo."]'::jsonb, true),
  ('sedef', 'p1', 'r4', 4, 'Fortalecimento da capacidade de gestão das OSCs', 'Materiais de orientação e, conforme a demanda, capacitação em gestão dos recursos e prestação de contas.', 'usuarios', '194 85% 38%', '', 'Plano de ação a partir das recomendações do estudo', '["A qualidade da execução das parcerias também é influenciada pela capacidade das OSCs de administrar os recursos recebidos, acompanhar as metas pactuadas e organizar as informações necessárias à prestação de contas. Essa dimensão é especialmente relevante em contextos nos quais organizações com diferentes níveis de estrutura administrativa e experiência passam a executar projetos financiados com recursos públicos.","Recomenda-se, nesse sentido, que a SEDEF avalie a oferta de materiais de apoio e ações de orientação voltadas à gestão dos recursos pelas OSCs parceiras, com conteúdo prático e diretamente relacionado às exigências da execução dos Termos de Fomento. Entre os temas que podem ser contemplados estão organização documental, controle financeiro do projeto, conciliação de extratos, planejamento de desembolsos, acompanhamento das metas previstas no plano de trabalho e preparação da prestação de contas.","A medida pode ser implementada de forma gradual. Em um primeiro momento, a Secretaria pode desenvolver materiais escritos de orientação básica, aproveitando dúvidas recorrentes e dificuldades identificadas durante o acompanhamento das parcerias. Conforme a demanda observada e a capacidade institucional disponível, esse apoio pode evoluir para ações de capacitação direcionadas às organizações contempladas.","Essa recomendação também se conecta à lógica do Orçamento para Resultados. À medida que as OSCs aprimoram seus mecanismos de acompanhamento da execução física e financeira, tornam-se mais viáveis registros mais consistentes sobre o que foi executado, quanto foi gasto, quais metas foram cumpridas e quais resultados foram alcançados. Isso favorece tanto a gestão da própria organização quanto a capacidade da SEDEF de acompanhar a relação entre recursos transferidos e entregas realizadas.","A iniciativa não pressupõe a criação imediata de uma estrutura ampla de capacitação. O foco deve estar na identificação dos pontos de maior dificuldade e na oferta de apoio proporcional às necessidades das organizações, priorizando inicialmente orientações de baixa complexidade e maior aplicabilidade prática.","Como referência, podem ser aproveitados materiais e práticas já desenvolvidos em outros contextos de gestão de parcerias, desde que adaptados às regras do MROSC, à regulamentação estadual e aos procedimentos adotados pela SEDEF.","A recomendação busca, portanto, reduzir dificuldades na execução dos projetos e fortalecer a capacidade das OSCs de administrar recursos públicos de forma aderente aos planos de trabalho e às exigências de acompanhamento e prestação de contas.","O que muda no processo: Apoia as organizações na gestão dos recursos, acompanhamento das metas, organização documental e prestação de contas. Complexidade de implementação: baixa a média, pode iniciar com materiais de apoio e avançar para ações de capacitação. Horizonte sugerido: curto a médio prazo."]'::jsonb, true),
  ('sedef', 'p1', 'r5', 5, 'Aplicação da metodologia de acompanhamento a futuros editais', 'Perguntas de gestão, indicadores e dados definidos na concepção dos próximos editais, e continuidade do painel.', 'repetir', '262 60% 52%', '', 'Plano de ação a partir das recomendações do estudo', '["A experiência do estudo demonstrou a possibilidade de estruturar uma leitura gerencial dos chamamentos públicos a partir da combinação entre informações do processo seletivo, execução financeira, distribuição territorial e temporalidade da execução. Embora os indicadores tenham sido desenvolvidos especificamente para o Edital nº 005/2024, a lógica utilizada pode servir como referência para o acompanhamento de outros instrumentos de transferência de recursos para OSCs promovidos pela SEDEF.","Recomenda-se, portanto, que, na preparação de futuros editais, a SEDEF defina previamente quais dimensões de desempenho deverão ser acompanhadas e quais informações precisarão ser registradas para viabilizar sua mensuração. Essa definição antecipada permitiria incorporar o monitoramento desde a concepção do chamamento, evitando que os indicadores sejam construídos posteriormente apenas a partir das informações que estiverem disponíveis.","Os seis indicadores desenvolvidos neste estudo podem constituir um ponto de partida para esse processo, mas sua aplicação não deve ocorrer de forma automática. Cada edital possui público, objeto, critérios de seleção, modelo de execução e características próprias. Dessa forma, indicadores relacionados à aptidão das propostas, execução financeira, distribuição territorial, ritmo dos desembolsos e duração do processo devem ser avaliados e adaptados de acordo com as perguntas de gestão relevantes para cada instrumento.","A principal oportunidade para os próximos editais está em complementar essas dimensões com informações sobre a execução das parcerias e seus resultados. A estruturação prévia de dados sobre beneficiários, metas e entregas permitirá desenvolver indicadores capazes de acompanhar, além da seleção e dos repasses, o que foi efetivamente realizado com os recursos transferidos. Essa evolução está diretamente relacionada à Recomendação 1, sobre estruturação e integração das informações das parcerias.","A recomendação também não pressupõe a reprodução do Painel Executivo desenvolvido para o Edital nº 005/2024. A ferramenta atual foi configurada especificamente para as bases, variáveis e indicadores disponíveis neste estudo. O elemento passível de replicação é a metodologia de acompanhamento, baseada na definição das perguntas de gestão, identificação dos dados necessários, construção dos indicadores e organização das informações em instrumentos que facilitem sua utilização pelas equipes responsáveis.","Dessa forma, a experiência do Edital nº 005/2024 pode funcionar como referência para a construção progressiva de um modelo de acompanhamento dos diferentes chamamentos realizados pela SEDEF, preservando as especificidades de cada instrumento e ampliando, ao longo do tempo, a utilização de informações de desempenho na gestão das parcerias com OSCs.","O que muda no processo: Incorpora desde a concepção dos novos chamamentos a definição das perguntas de gestão, dados necessários e indicadores de acompanhamento, adaptados às características de cada edital. Complexidade de implementação: baixa, reaproveita os aprendizados metodológicos do estudo. Horizonte sugerido: curto prazo."]'::jsonb, true),
  ('sedef', 'p1', 'r6', 6, 'Integração dos resultados do acompanhamento ao ciclo orçamentário', 'Indicadores dos editais como insumo complementar na discussão da proposta orçamentária.', 'grafico', '18 78% 50%', '', 'Plano de ação a partir das recomendações do estudo', '["Os resultados produzidos pelo estudo podem ser utilizados não apenas pela SEDEF no acompanhamento dos editais, mas também pela SEFA como insumo para a análise da execução orçamentária e para a qualificação das discussões relacionadas à elaboração e revisão das peças orçamentárias.","Recomenda-se que, nos próximos ciclos, os indicadores e evidências produzidos sobre os editais de transferência de recursos a OSCs sejam considerados nos momentos de discussão da proposta orçamentária, especialmente quando houver necessidade de avaliar manutenção, ampliação ou redimensionamento dos recursos destinados a esse tipo de instrumento.","No caso do Edital nº 005/2024, a análise mostrou que a leitura orçamentária pode ser enriquecida quando o volume de recursos previsto e executado é observado em conjunto com informações sobre quantidade de propostas aptas e pagas, distribuição entre eixos, abrangência territorial e ritmo de desembolso. A incorporação futura de dados sobre beneficiários, entregas e resultados poderá ampliar ainda mais essa capacidade de análise.","Para a SEFA, essa abordagem permite que a discussão orçamentária avance gradualmente de uma leitura centrada apenas na execução financeira para uma análise que considere também o desempenho dos instrumentos financiados. Em futuros ciclos da PLOA, por exemplo, essas evidências podem subsidiar questionamentos sobre o volume de recursos requerido, a capacidade de execução observada, a distribuição dos recursos e os resultados associados às dotações destinadas aos editais.","Essa integração não pressupõe a criação de critérios automáticos de alocação orçamentária com base nos indicadores do estudo. O uso recomendado é analítico e complementar, de modo que as evidências produzidas pelos Estudos da Qualidade do Gasto contribuam para fundamentar as discussões entre a SEFA e os órgãos setoriais durante o processo de planejamento e elaboração orçamentária.","No caso das despesas vinculadas à Ação 8418, Políticas Públicas da Criança e do Adolescente, os resultados do acompanhamento do edital podem complementar a leitura da execução da ação, preservando-se a distinção de que a ação financia outras despesas e iniciativas além do Edital nº 005/2024.","O que muda no processo: Utiliza os indicadores e evidências produzidos pelo acompanhamento e pelos Estudos da Qualidade do Gasto como insumo para as discussões entre SEFA e órgãos setoriais sobre manutenção, ampliação ou redimensionamento de recursos, especialmente durante a elaboração da PLOA. Complexidade de implementação: baixa a média, depende principalmente de incorporação da rotina analítica aos ritos orçamentários. Horizonte sugerido: curto a médio prazo."]'::jsonb, true)
on conflict (org_id, estudo_id, rid) do nothing;

insert into public.acoes (org_id, estudo_id, codigo, rid, ordem, titulo, descricao, responsavel, area,
                          pessoa, produto, resultado, horizonte, horizonte_original, natureza, ciclo,
                          origem, status) values
  ('seab', 'p1', '1.1', 'r1', 1, 'Mapeamento dos gargalos municipais no processo de cadastramento', 'Levantar, junto aos núcleos regionais da SEAB e aos municípios com maior queda de beneficiários, os pontos críticos do fluxo de cadastramento: exigências documentais, frequência de atualização, capacidade das equipes municipais e tempo médio entre a solicitação e a ativação do benefício. A ação deverá utilizar como insumo a relação de municípios classificados por categoria de variação do número de beneficiários no período 2023-2025, contemplando os estratos de queda superior a 20%, queda entre 10% e 20%, estabilidade entre ±10% e crescimento superior a 10%. Priorizar os 111 municípios com queda acima de 20% no período 2023-2025.', 'SEAB / Núcleos Regionais / CRPLC / CMPLC', '', '', 'Relatório de diagnóstico dos gargalos, contendo a relação de municípios por estrato de variação de beneficiários e proposta de simplificação do fluxo de cadastramento.', 'Pontos de perda de beneficiários identificados por município e proposta de simplificação do fluxo apresentada aos 111 municípios prioritários.', 'Curto prazo', 'Curto prazo', 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '1.2', 'r1', 2, 'Aplicação da pesquisa com beneficiários e público elegível não atendido', 'Implementar o instrumento de pesquisa desenvolvido no Estudo da Qualidade do Gasto (480 entrevistas estratificadas por perfil de município, Módulos A e B). Utilizar como canal primário os pontos de entrega do leite; como canal secundário as UBS e os CRAS; e como canal complementar formulário digital via WhatsApp. Analisar os resultados para identificar os fatores de maior impacto sobre a adesão e permanência no programa.', 'SEAB / Municípios / Sec. Munic. de Saúde e Assist. Social', '', '', 'Relatório analítico com os resultados da pesquisa e recomendações de melhoria', 'Hipóteses sobre as barreiras de acesso confirmadas ou descartadas com dados primários, orientando as demais ações de cobertura.', 'Curto prazo', 'Curto prazo', 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '1.3', 'r1', 3, 'Campanha de comunicação orientada ao público elegível', 'Desenvolver e implementar campanha de comunicação com linguagem acessível sobre o PLC, dirigida às famílias elegíveis não atendidas. Utilizar como canais: pontos de entrega do leite, UBS, CRAS, escolas municipais e aplicativos de mensagens já usados pelas prefeituras. O conteúdo deve comunicar claramente os critérios de elegibilidade, o processo de cadastramento, os pontos de distribuição e os benefícios nutricionais do programa. Priorizar municípios com taxa de cobertura abaixo de 30%. A campanha deverá ser alinhada à área de Comunicação da SEAB e considerar as alterações em discussão na legislação do Programa, inclusive quanto à sua denominação.', 'SEAB / CRPLC / CMPLC', '', '', 'Material de comunicação produzido e distribuído; nº de municípios alcançados', 'Campanha veiculada nos pontos de entrega, unidades de saúde, CRAS e escolas, com novos cadastros nos municípios alcançados.', 'Médio prazo', 'Curto prazo', 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '1.4', 'r1', 4, 'Estruturação do protocolo de busca ativa com saúde e assistência social', 'Formalizar protocolo de cooperação com a Secretaria de Estado da Saúde (SESA) e a Secretaria de Estado do Desenvolvimento Social e Família (SEDEF) para que agentes comunitários de saúde e técnicos do CRAS identifiquem e encaminhem famílias elegíveis durante visitas domiciliares e atendimentos rotineiros. Definir responsabilidades, fluxos de encaminhamento, capacitação mínima e metas de identificação por município.', 'SEAB / SESA / SEDEF', '', '', 'Protocolo assinado e equipes treinadas nos municípios prioritários', 'Agentes comunitários de saúde e técnicos dos CRAS encaminhando famílias elegíveis ao programa em rotina regular.', 'Médio prazo', 'Médio prazo', 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '1.5', 'r1', 5, 'Análise dos critérios de elegibilidade com cruzamento do CadÚnico', 'Cruzar os dados de beneficiários e público elegível do PLC com a base do CadÚnico para dimensionar o contingente de famílias elegíveis não cadastradas no programa. Avaliar, a partir dos resultados, se há caso para revisão do critério de renda (atualmente até 1/2 salário mínimo regional) ou para ajustes no processo de inscrição que facilitem o acesso de famílias vulneráveis não cadastradas no CadÚnico.', 'SEAB / SEDEF', '', '', 'Nota técnica com simulações de impacto e recomendações sobre os critérios', 'Decisão da SEAB sobre revisar ou manter o critério de renda, registrada e fundamentada nas simulações.', 'Médio prazo', 'Médio prazo', 'Normativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '1.6', 'r1', 6, 'Inclusão de entidades beneficentes como canal adicional de distribuição', 'Avaliar a viabilidade legal e operacional de estender o fornecimento do leite do PLC a entidades beneficentes cadastradas em programas sociais do Estado. O modelo permitiria ampliar o alcance do programa sem exigir novo processo de habilitação de usinas e com potencial de redução do custo médio por beneficiário. O estudo deve contemplar: mapeamento das entidades elegíveis, avaliação jurídica do modelo de fornecimento, estimativa de demanda adicional e proposta de alteração do edital de credenciamento de usinas.', 'SEAB / Procuradoria / SEFA', '', '', 'Estudo de viabilidade concluído; proposta de alteração do edital elaborada', 'Definição sobre incluir entidades beneficentes como canal de distribuição, com o edital de credenciamento revisto quando aprovada.', 'Médio prazo', 'Médio prazo', 'Normativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '1.7', 'r1', 7, 'Cruzamento com o CadÚnico para identificação de motivos de saída do programa', 'Como etapa inicial, avaliar, com a CELEPAR e a SEDEF, a viabilidade técnica e operacional de extrair do sistema do Programa relatório mensal das crianças desligadas, com CPF e motivo do desligamento, inclusive por faltas, que servirá de base para o cruzamento. Cruzar a base de beneficiários e ex-beneficiários do PLC com o CadÚnico para identificar, entre as famílias que deixaram o programa, os motivos de saída do cadastro (atualização cadastral, mudança de renda, mudança de município, ausência de retirada do leite, entre outros) e dimensionar o contingente de famílias em situação de pobreza inscritas no CadÚnico que não constam como beneficiárias do PLC. Os resultados devem subsidiar a confirmação ou o ajuste das Hipóteses C, D, E e F sobre as causas da queda de beneficiários, complementando a análise da Ação 1.5.', 'SEAB / MDS / SEDEF', '', '', 'Relatório de cruzamento de dados com tipificação dos motivos de saída e dimensionamento das famílias pobres não atendidas', 'Motivos de saída do programa tipificados e contingente de famílias elegíveis não atendidas dimensionado, subsidiando a análise dos critérios.', 'Médio prazo', 'Médio prazo', 'Normativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '2.1', 'r2', 1, 'Implantação de registro digital de distribuição nos pontos de entrega', 'Implementar registro digital de confirmação de retirada do leite nos pontos de entrega, vinculado ao cadastro de beneficiários. O sistema deve permitir o registro tempestivo das retiradas e das faltas, com geração de alertas semanais para apoiar a gestão das sobras de leite dentro da própria semana de ocorrência das ausências. A solução também deverá registrar as faltas de forma compatível com a regra operacional já existente de desligamento automático de beneficiários que acumulam três faltas consecutivas em um mês, desde que essas ausências estejam devidamente registradas. Recomenda-se iniciar a implementação por projeto-piloto em municípios de médio porte antes da expansão estadual. A funcionalidade deverá ser contemplada no desenvolvimento do novo sistema do Programa, na etapa de definição de sua estrutura e funcionalidades.', 'SEAB / Municípios / CELEPAR', '', '', 'Sistema de registro implantado e em operação nos municípios-piloto', 'Retirada do leite confirmada digitalmente nos pontos de entrega, com alertas de não-retirada disponíveis à coordenação.', 'Médio prazo', 'Médio prazo', 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '2.2', 'r2', 2, 'Revisão do mecanismo de bônus de qualidade do LCR', 'Avaliar se o mecanismo de bônus de qualidade (1% e 2%) está calibrado de forma adequada para continuar incentivando melhorias nos padrões do leite cru, considerando que a proporção de usinas com bônus cresceu de 31% para 49% entre 2023 e 2025. Considerar a introdução de uma terceira faixa de bônus ou de metas progressivas para manter o efeito indutor do mecanismo.', 'SEAB / DERAL / Adapar / IDR / APCBRH / MAPA / CTPLC', '', '', 'Proposta de revisão do edital com novo escalonamento de bônus', 'Novo escalonamento do bônus vigente no credenciamento, com as usinas migrando para as faixas de maior qualidade.', 'Médio prazo', 'Médio prazo', 'Normativa', null, 'relatorio', 'nao_iniciada'),
  ('seab', 'p1', '2.3', 'r2', 3, 'Integração com sistema para monitoramento do estado nutricional', 'Estruturar, em conjunto com a Secretaria de Estado da Saúde (SESA), a integração de dados entre o PLC e um sistema que permita identificar o estado nutricional de crianças beneficiárias e elegíveis não atendidas, permitindo identificar o estado nutricional de crianças beneficiárias e elegíveis não atendidas e acompanhar sua evolução ao longo do tempo. A rotina deve viabilizar a comparação periódica entre o estado nutricional de crianças atendidas e não atendidas pelo programa, subsidiando a avaliação da efetividade nutricional do PLC.', 'SEAB / SESA', '', '', 'Rotina de integração de dados implantada; relatório-piloto de acompanhamento nutricional', 'Estado nutricional das crianças beneficiárias e das elegíveis não atendidas acompanhado em rotina periódica.', 'Médio prazo', 'Médio prazo', 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '1.1', 'r1', 1, 'Comparar a eficiência de custo por metro quadrado dentro de faixas semelhantes de área e reavaliar os critérios à medida que as obras dos cortes 2024 e 2025 encerram', '', 'SEDEST e IAT', '', '', 'Critérios de eficiência recalibrados por faixa de porte, com base ampliada pelas obras encerradas dos cortes 2024 e 2025.', 'Comparações de eficiência feitas dentro de faixas de porte semelhantes, com a base ampliada pelas obras encerradas dos cortes 2024 e 2025.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '2.1', 'r2', 1, 'Estabelecer prazo de referência de implantação de 36 meses', 'Estabelecer prazo de referência de implantação de 36 meses, independente do porte da obra', 'SEDEST e IAT', '', '', 'Prazo de referência de 36 meses formalizado como exigência padrão do convênio, com justificativa técnica exigida acima desse limite.', 'Convênios celebrados com o prazo de 36 meses como exigência padrão, e obras que o excedem sob justificativa técnica.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '2.2', 'r2', 2, 'Direcionar acompanhamento técnico ativo à fase de execução', 'Direcionar acompanhamento técnico ativo à fase de execução, com rotina de medição periódica, responsável formalmente designado no município e intensidade calibrada por fatores de risco da obra; investigar as obras acima de 60 meses', 'IAT e municípios', '', '', 'Rotina de medição periódica implantada, com responsável formalmente designado em cada município e agenda regular de acompanhamento do IAT.', 'Obras acompanhadas na fase de execução com medição periódica e responsável designado no município, reduzindo a dispersão de prazos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '2.3', 'r2', 3, 'Registrar na base do projeto os marcos intermediários da execução', 'Registrar na base do projeto os marcos intermediários da execução (edital, homologação, ordem de serviço, medições e paralisações)', 'SEDEST e IAT', '', '', 'Base do projeto registrando os marcos intermediários de cada obra: edital, homologação, ordem de serviço, medições e paralisações com o respectivo motivo.', 'Gargalo específico de cada obra localizável na base, a partir dos marcos de edital, ordem de serviço, medições e paralisações.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '3.1', 'r3', 1, 'Instituir a coleta de dados primários ao parque', 'Instituir a coleta de dados primários ao parque (área plantada, mudas, taxa de sobrevivência, área recuperada e permeável)', 'IAT e municípios', '', '', 'Rotina de coleta de dados primários implantada nos parques: área efetivamente plantada, número de mudas, taxa de sobrevivência, área recuperada e área permeável.', 'Efeito ambiental de cada parque medido por dado próprio, e não por indicador municipal usado como aproximação.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '3.2', 'r3', 2, 'Confirmar a atribuição da melhora ambiental ao parque', 'Confirmar a atribuição da melhora ambiental ao parque, comparando municípios atendidos com vizinhos não atendidos', 'SEDEST e IAT', '', '', 'Estudo comparativo entre municípios atendidos e vizinhos não atendidos, com conclusão sobre a atribuição do ganho florestal ao parque.', 'Conclusão registrada sobre a melhora florestal ser atribuível ao parque ou à tendência regional de uso do solo.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '4.1', 'r4', 1, 'Padronizar os instrumentos de gestão do projeto', 'Padronizar os instrumentos de gestão do projeto (estrutura de termo de referência e edital, catálogo de especificações técnicas e planilha orçamentária referencial), preservada a adequação de cada obra às condições locais', 'SEDEST e IAT', '', '', 'Conjunto padronizado de instrumentos disponibilizado aos municípios: estrutura de termo de referência e edital, catálogo de especificações técnicas e planilha orçamentária referencial.', 'Municípios aderindo ao projeto com termo de referência, edital e planilha orçamentária de referência comuns.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '4.2', 'r4', 2, 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário', 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário, com base na aba Eficiência do Investimento do painel', 'SEDEST e IAT', '', '', 'Faixas de custo de referência por porte publicadas e aplicadas na seleção do ciclo, com exigência de justificativa técnica acima do teto de referência.', 'Convênios do ciclo triados pela faixa de custo do seu porte, com justificativa técnica exigida acima do teto de referência.', null, null, null, 2026, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '4.3', 'r4', 3, 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário', 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário, com base na aba Eficiência do Investimento do painel', 'SEDEST e IAT', '', '', 'Faixas de custo de referência por porte publicadas e aplicadas na seleção do ciclo, com exigência de justificativa técnica acima do teto de referência.', 'Convênios do ciclo triados pela faixa de custo do seu porte, com justificativa técnica exigida acima do teto de referência.', null, null, null, 2027, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '4.4', 'r4', 4, 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário', 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário, com base na aba Eficiência do Investimento do painel', 'SEDEST e IAT', '', '', 'Faixas de custo de referência por porte publicadas e aplicadas na seleção do ciclo, com exigência de justificativa técnica acima do teto de referência.', 'Convênios do ciclo triados pela faixa de custo do seu porte, com justificativa técnica exigida acima do teto de referência.', null, null, null, 2028, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '4.5', 'r4', 5, 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário', 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário, com base na aba Eficiência do Investimento do painel', 'SEDEST e IAT', '', '', 'Faixas de custo de referência por porte publicadas e aplicadas na seleção do ciclo, com exigência de justificativa técnica acima do teto de referência.', 'Convênios do ciclo triados pela faixa de custo do seu porte, com justificativa técnica exigida acima do teto de referência.', null, null, null, 2029, 'relatorio', 'nao_iniciada'),
  ('sedest', 'p1', '4.6', 'r4', 6, 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário', 'Adotar as faixas iniciais de custo de referência por porte e recalibrá-las a cada ciclo orçamentário, com base na aba Eficiência do Investimento do painel', 'SEDEST e IAT', '', '', 'Faixas de custo de referência por porte publicadas e aplicadas na seleção do ciclo, com exigência de justificativa técnica acima do teto de referência.', 'Convênios do ciclo triados pela faixa de custo do seu porte, com justificativa técnica exigida acima do teto de referência.', null, null, null, 2030, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '1.1', 'r1', 1, 'Elaborar o DFD antes do ETP', 'Aplicável aos fluxos de dispensa de licitação, inexigibilidade de licitação, aquisição via ata de registro de preços e pregão eletrônico (comum, SRP e importação). A Divisão Técnica do CEMEPAR elabora o DFD como primeira atividade e, quando houver ETP, elabora o ETP em seguida.
Aprovação: DAD/CGOV.', 'CEMEPAR', '', 'André Luiz', 'Fluxos dos seis processos e orientações de instrução atualizados, com o DFD como etapa anterior ao ETP.', 'Necessidade caracterizada de forma objetiva antes do ETP, com planejamento mais coerente em todos os processos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '1.2', 'r1', 2, 'Verificar se todos os itens têm preço cotado e reiniciar o trâmite só dos itens sem cotação', 'Aplicável às dispensas e inexigibilidades. Após validar especificações, se houver itens sem preço cotado, abre-se processo à parte somente para os itens sem cotação, avançando normalmente os itens já cotados.
Aprovação: DAD/CGOV.', 'CEMEPAR', '', '', 'Fluxos de dispensa e de inexigibilidade atualizados com a verificação de cotação integral e a orientação para reiniciar apenas os itens sem preço.', 'Itens já cotados avançando sem aguardar os demais, sem paralisação integral do processo.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '1.3', 'r1', 3, 'Verificar a validade das certidões negativas na anexação e notificar o fornecedor quando houver irregularidade', 'Aplicável às dispensas, inexigibilidades e atas. Ao anexar as certidões, a Divisão Administrativa do CEMEPAR verifica se há certidões vencidas e notifica o fornecedor.', 'FUNSAÚDE - Setor de Empenhos / CEMEPAR', '', '', 'Fluxos atualizados com a verificação de validade das certidões na anexação e orientação para notificar o fornecedor e registrar a diligência no processo.', 'Irregularidade nas certidões tratada já na instrução, com a diligência registrada no processo e menor risco de formalização com fornecedor irregular.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.1', 'r2', 1, 'Avaliar a mudança do momento de assinatura do ETP', 'Avaliar a concentração da assinatura do ETP pelo Secretário em momento mais adiante do fluxo, preferencialmente antes da autorização da cotação.', 'DAD / Gabinete', '', '', 'Decisão registrada sobre o momento da assinatura do ETP e fluxos ajustados, se aprovada a mudança.', 'Menos assinaturas sequenciais do Secretário no início do processo e tramitação mais curta.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.2', 'r2', 2, 'Racionalizar a etapa de análise do memorando e inclusão do despacho de autorização', 'Aprofundar o entendimento dos fatores que prolongam a análise do Gabinete (hoje de 20 a 40 dias) e adotar padronização e checklists.', 'GS - DAD / CEMEPAR', '', '', 'Fatores da demora identificados e medidas de racionalização da etapa definidas.', 'Análise do memorando e despacho de autorização em prazo menor que os atuais 20 a 40 dias.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.3', 'r2', 3, 'Consolidar em ato único as assinaturas sequenciais do edital', 'Nos pregões eletrônicos, avaliar a consolidação das assinaturas consecutivas da DAD/CGOV e CPL em ato único antes da fase externa.', 'DAD', '', '', 'Decisão registrada sobre a consolidação das assinaturas e fluxos dos pregões ajustados, se aprovada.', 'Edital publicado com uma etapa de assinatura a menos antes da fase externa.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.4', 'r2', 4, 'Redefinir a consulta à disponibilidade de ata para a instrução dos processos', 'A divisão técnica solicitante analisa a disponibilidade da ata antes de abrir o protocolo de compra, apoiada em sistema de TI.', 'CEMEPAR', '', '', 'Consulta à disponibilidade da ata feita pela divisão técnica antes da abertura do protocolo, com apoio do sistema.', 'Protocolos de compra abertos já com a disponibilidade da ata conferida, sem retrabalho na instrução.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.5', 'r2', 5, 'Consultar a DAD sobre a exigência da lista nominal de pacientes no saque da ata', 'Consultar a DAD sobre a real necessidade da lista no SISMEDEX para alinhar a retirada à demanda inicial.', 'DAD', '', '', 'Resposta da DAD registrada sobre a exigência da lista nominal no saque da ata.', 'Saque da ata alinhado à demanda inicial, conforme a regra confirmada pela DAD.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.6', 'r2', 6, 'Impedir o andamento de reajuste de preço enquanto houver processo de compra em curso', 'Avaliar alternativa que impeça a tramitação de reajuste quando houver processo de compra em curso, evitando divergências com o empenho.', 'CEMEPAR - DAD', '', '', 'Regra definida para o tratamento de reajuste com processo de compra em curso.', 'Ordens de compra emitidas sem divergência de preço em relação ao empenho.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.7', 'r2', 7, 'Vincular o envio dos medicamentos importados à ordem de compra, e não à carta de crédito', 'Revisar a minuta contratual para que o envio pelo fornecedor fique vinculado à ordem de compra emitida.', 'CEMEPAR - DAD', '', '', 'Minuta contratual revisada, com o envio dos medicamentos vinculado à ordem de compra.', 'Envio dos medicamentos importados sem esperar a emissão da carta de crédito.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.8', 'r2', 8, 'Avaliar o pagamento por remessa no lugar da carta de crédito', 'Analisar a adoção de pagamento por remessa bancária nas importações, retirando a etapa de carta de crédito.', 'FUNSAÚDE - DAD', '', '', 'Análise registrada sobre a adoção do pagamento por remessa nas importações.', 'Processo de importação sem a etapa bancária da carta de crédito, se o modelo for adotado.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.9', 'r2', 9, 'Digitalizar o registro de entrada e recebimento', 'Implantar formulário digital de entrada na CAF substituindo o registro físico.', 'CEMEPAR - NII', '', '', 'Formulário digital de recebimento substituindo o registro físico, com os dados integrados ao fluxo de entrada.', 'Entrada de medicamentos registrada digitalmente, com rastreabilidade do fluxo e menos inconsistências no recebimento.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '2.10', 'r2', 10, 'Eliminar os preenchimentos manuais de planilhas na entrada de medicamentos', 'Sistema integrado para eliminação de planilhas preenchidas à mão no recebimento e SYSMED.', 'NII - CEMEPAR', '', '', 'Registros da entrada feitos em sistema, sem planilhas preenchidas à mão.', 'Dados de recebimento consistentes, com menos erros de coleta.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '3.1', 'r3', 1, 'Implantar o sistema integrado de planejamento de compras', 'Centralizar dados dispersos (contratos, atas, estoques, demandas, histórico) em base tecnológica única.', 'NII - CEMEPAR - DAD', '', '', 'Sistema em operação, consolidando contratos vigentes, atas, demandas, estoques, histórico de consumo, protocolos e prazos críticos em base única.', 'Planejamento das compras feito sobre base única, com antecipação de demanda e menos aquisições emergenciais.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '3.2', 'r3', 2, 'Uniformizar os critérios de condução: níveis de serviço nas etapas críticas e protocolo de urgência no e-Protocolo', 'Estabelecer SLAs de referência e normatizar critérios para o uso de tarjas de urgência.', 'DAD - CEMEPAR', '', '', 'Níveis de serviço definidos para as etapas críticas e protocolo de urgência normatizado no e-Protocolo.', 'Tramitação previsível, com prazos de referência nas etapas críticas e priorização por critério objetivo.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '3.3', 'r3', 3, 'Eliminar a duplicidade de informações entre DFD e ETP', 'Revisar modelos para suprimir repetições de conteúdo entre DFD e ETP.', 'DAD', '', '', 'Modelos de DFD e ETP revistos, sem repetição de conteúdo entre os dois documentos.', 'Instrução mais objetiva, com menos retrabalho na elaboração dos documentos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '4.1', 'r4', 1, 'Designar os responsáveis por frente de trabalho', 'Ato interno designando responsáveis pelas frentes de coordenação, processos, sistemas, indicadores e comunicação.', 'NPS', '', '', 'Ato interno de designação dos responsáveis por frente de trabalho: coordenação técnico-operacional, processos e padronização, sistemas e dados, indicadores e painel, e comunicação.', 'Cada frente de trabalho com encaminhamento definido e decisões rastreáveis, sem depender de articulação informal.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '4.2', 'r4', 2, 'Validar as recomendações com as instâncias superiores e as áreas envolvidas', 'Confirmar entendimentos e pactuar responsabilidades com a alta administração.', 'NPS', '', '', 'Registro consolidado de deliberações e dependências, resultante da rodada de alinhamento com as áreas envolvidas e a alta administração.', 'Recomendações que dependem de outras áreas validadas pela alta administração antes da implantação.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '4.3', 'r4', 3, 'Consolidar o backlog único, organizado por dependências', 'Backlog reunindo todas as ações classificadas por dependência técnica e institucional.', 'NPS', '', '', 'Backlog único de implementação, com cada medida classificada entre implantável pelo CEMEPAR, dependente de validação institucional e dependente de suporte de outras áreas.', 'Medidas implantadas em ordem lógica, com as estruturantes iniciando apenas após os requisitos mínimos definidos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '4.4', 'r4', 4, 'Institucionalizar o monitoramento por indicadores e o rito bimestral de análise crítica', 'Rito permanente bimestral para avaliação de gargalos e reincidências.', 'CEMEPAR', '', '', 'Rito bimestral instituído, com registro dos resultados e dos encaminhamentos de cada ciclo.', 'Desempenho dos processos analisado a cada bimestre, com resultados e encaminhamentos registrados.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '4.5', 'r4', 5, 'Conduzir ações corretivas, preventivas e de aperfeiçoamento', 'Ajustes e correções derivados das análises bimestrais dos indicadores.', 'CEMEPAR', '', '', 'Plano de ações corretivas, preventivas e de aperfeiçoamento derivado da análise crítica, com responsáveis e prazos.', 'Desvios identificados no painel tratados por ação com responsável e prazo definidos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '5.1', 'r5', 1, 'Disponibilizar o painel em ambiente de rede interna da SESA/PR ou do CEMEPAR', 'Hospedar o painel em rede interna corporativa sem arquivos soltos por e-mail.', 'NII', '', '', 'Painel hospedado em rede interna da SESA ou do CEMEPAR, com versão única e acesso controlado.', 'Gestores consultando o painel diretamente na rede, em versão única, sem troca de arquivos avulsos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '5.2', 'r5', 2, 'Estabelecer rotina automatizada de extração e atualização dos dados do painel', 'Eliminar carga manual de dados estabelecendo rotinas automatizadas.', 'DAD - NII', '', '', 'Rotina automatizada de extração e atualização dos dados do painel, com periodicidade definida.', 'Painel refletindo o desempenho corrente, sem defasagem por carga manual das bases.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sesa', 'p1', '5.3', 'r5', 3, 'Integrar e padronizar as bases de dados do painel', 'Padronizar colunas e campos de origem das licitações e contratações diretas.', 'DAD - NII', '', '', 'Bases de origem padronizadas nas colunas e nos campos que sustentam os indicadores hoje reservados.', 'Indicadores hoje reservados passando a ser apurados, com os campos necessários preenchidos na origem.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '1.1', 'r1', 1, 'Plano de intervenção de nivelamento no quarto quartil de água', 'Plano de intervenção de nivelamento no quarto quartil de água, aproximando as unidades de gasto excedente da mediana do cluster, de forma faseada (primeiro passo: patamar mediano do terceiro quartil)', 'SEED e Núcleos Regionais de Educação', '', '', 'Plano faseado de nivelamento das escolas do quarto quartil de água, com meta inicial no patamar mediano do terceiro quartil do cluster.', 'Escolas do quarto quartil de água em trajetória de aproximação à mediana do seu cluster, a partir do patamar do terceiro quartil.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '2.1', 'r2', 1, 'Plano de intervenção de cobertura ampla no quarto quartil de energia', 'Plano de intervenção de cobertura ampla no quarto quartil de energia (eficiência em climatização e iluminação)', 'SEED e Núcleos Regionais de Educação', '', '', 'Plano de cobertura ampla no quarto quartil de energia, dirigido à eficiência em climatização e iluminação.', 'Escolas do quarto quartil de energia com intervenções de climatização e iluminação em curso, em cobertura ampla e não pontual.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '3.1', 'r3', 1, 'Verificação de campo das escolas atípicas de consumo alto de água', 'Verificação de campo das escolas atípicas de consumo alto de água (vazamento, perda e erro de medição), antes de qualquer meta', 'SEED e Núcleos Regionais de Educação', '', '', 'Relatório de verificação de campo das escolas atípicas de consumo alto de água, com a causa identificada em cada caso: vazamento, perda ou erro de medição.', 'Causa do consumo atípico conhecida em cada escola, distinguindo vazamento, perda e erro de medição antes de qualquer meta.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '4.1', 'r4', 1, 'Auditoria cadastral e de medição das unidades com consumo implausivelmente baixo de água e energia', '', 'SEED e Núcleos Regionais de Educação', '', '', 'Auditoria cadastral e de medição concluída nas unidades de consumo implausivelmente baixo, com cadastro e medição corrigidos.', 'Cadastro e medição corrigidos nas unidades de consumo implausível, devolvendo confiabilidade à base de comparação.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '5.1', 'r5', 1, 'Definição e acompanhamento do indicador de gasto por aluno por mês e dos alvos por cluster', 'Definição e acompanhamento do indicador de gasto por aluno por mês e dos alvos por cluster, com atualização da base, das tarifas e recálculo dos quartis e da mediana', 'SEED (Planejamento da Rede e Dados)', '', '', 'Indicador de gasto por aluno por mês institucionalizado, com alvos por cluster e rotina de recálculo dos quartis e da mediana.', 'Gasto por aluno acompanhado em rotina pela Secretaria, com quartis e medianas recalculados a cada nova safra de dados.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '5.2', 'r5', 2, 'Difusão de boas práticas a partir das escolas de referência de cada cluster', '', 'SEED e Núcleos Regionais de Educação', '', '', 'Catálogo de boas práticas das escolas de referência de cada cluster, difundido aos Núcleos Regionais de Educação.', 'Práticas das escolas de referência difundidas aos Núcleos Regionais e replicadas em unidades do mesmo cluster.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seed', 'p1', '5.3', 'r5', 3, 'Registro da ação orçamentária que custeia as despesas de água e energia e acompanhamento físico-financeiro da execução', '', 'SEED (Núcleo Fazendário Setorial)', '', '', 'Despesas de água e energia identificadas na ação orçamentária, com acompanhamento físico-financeiro periódico da execução.', 'Execução de água e energia acompanhada física e financeiramente, permitindo relacionar dotação e desempenho no ciclo seguinte.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seil', 'p1', '1.1', 'r1', 1, 'Constituição da Comissão de Monitoramento e Avaliação do Programa', 'Formalizar a composição e as atribuições da Comissão de M&amp;A do programa, definindo os membros, a periodicidade de reuniões e o rito de homologação dos Relatórios Técnicos de Monitoramento, em conformidade com o disposto no Decreto Estadual nº 3.513/2016.', 'SEIL', '', '', 'Portaria ou documento formal de constituição da Comissão', 'Comissão constituída e primeira reunião realizada.', null, null, 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seil', 'p1', '1.2', 'r1', 2, 'Definição dos responsáveis pela apuração de cada indicador e dos fluxos de coleta de dados', 'Identificar, para cada um dos cinco indicadores, os servidores ou equipes responsáveis pela apuração periódica, as fontes de dados a serem utilizadas, os prazos de coleta e os formatos de registro. Formalizar esse fluxo em documento interno para garantir continuidade mesmo em caso de mudança de equipe.', 'SEIL / AMP', '', '', 'Documento de fluxo de coleta de dados por indicador', 'Fluxo aprovado e comunicado às equipes responsáveis.', null, null, 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seil', 'p1', '1.3', 'r1', 3, 'Elaboração do modelo de Relatório Técnico de Monitoramento', 'Desenvolver o modelo padrão do Relatório Técnico de Monitoramento do programa, incluindo seções para registro dos resultados de cada indicador, análise de cumprimento de metas, identificação de fatores que influenciaram o desempenho e encaminhamentos para o período seguinte.', 'SEIL', '', '', 'Modelo de relatório aprovado e disponível para uso', 'Primeiro relatório trimestral elaborado com base no modelo.', null, null, 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seil', 'p1', '1.4', 'r1', 4, 'Realização da primeira Reunião de Aprendizado Estratégico', 'Conduzir a primeira Reunião de Aprendizado Estratégico ao final do primeiro semestre de implementação do programa, com base nos resultados dos indicadores apurados. Utilizar o encontro para identificar fatores que influenciaram o desempenho observado e deliberar sobre eventuais ajustes na execução.', 'SEIL / AMP / Comissão de M&amp;A', '', '', 'Registro da reunião com achados e encaminhamentos documentados', 'Reunião realizada dentro do prazo semestral.', null, null, 'Administrativa', null, 'relatorio', 'nao_iniciada'),
  ('seil', 'p1', '1.5', 'r1', 5, 'Padronização dos relatórios de monitoramento da AMP', 'Assegurar que os relatórios de monitoramento trimestrais submetidos pela AMP passem a conter, para cada projeto, as informações necessárias à apuração do indicador de efetividade: número do processo de convênio, município, associação, objeto, data de abertura do processo, data de celebração do convênio (quando aplicável) e órgão financiador.', 'AMP (preenchimento) / SEIL (validação)', '', '', 'Layout padronizado de relatório de monitoramento incorporando os campos do indicador de efetividade', 'Layout validado e em uso a partir do próximo ciclo de relatórios.', null, null, 'Técnica', null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '1.1', 'r1', 1, 'Formalização de responsáveis por base', 'Designar, para cada uma das catorze bases que alimentam o painel, um responsável técnico pela atualização periódica e validação de qualidade dos dados.', 'SETI / Áreas técnicas', '', '', 'Matriz de responsabilidades por base, com periodicidade definida', 'As catorze bases que alimentam o painel atualizadas por responsável designado, na periodicidade definida.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '1.2', 'r1', 2, 'Tratamento de bases incompletas', 'Avaliar e equacionar as lacunas identificadas nas bases de Suplementação e de cruzamento CBO2/RAIS, hoje com baixa cobertura de indicadores no painel.', 'SETI / SEFA', '', '', 'Bases complementadas ou justificativa técnica registrada para as lacunas remanescentes', 'Lacunas das bases de Suplementação e do cruzamento CBO2/RAIS equacionadas ou justificadas, com o painel refletindo a cobertura real.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '1.3', 'r1', 3, 'Ampliação da série histórica orçamentária', 'Estender a cobertura da base de execução orçamentária (Relatório da Despesa 8050 / SELO Paraná) para viabilizar análise de cinco anos.', 'SETI / SEFA', '', '', 'Série histórica ampliada e compatibilizada com os indicadores acadêmicos do INEP', 'Análise de cinco anos viabilizada, permitindo distinguir tendência de oscilação pontual.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '2.1', 'r2', 1, 'Incorporação do painel ao ciclo da LOA', 'Utilizar o painel como insumo técnico na elaboração da proposta orçamentária anual das sete IEES junto à SEFA.', 'SETI', '', '', 'Rotina formal de consulta ao painel documentada no processo de elaboração orçamentária', 'Proposta orçamentária das sete instituições elaborada com o painel como insumo documentado.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '2.2', 'r2', 2, 'Rotina de leitura compartilhada com as IEES', 'Instituir reuniões periódicas entre SETI e as sete instituições para leitura conjunta dos indicadores do painel.', 'SETI', '', '', 'Calendário de reuniões e atas de leitura compartilhada', 'SETI e as sete instituições lendo os indicadores em conjunto, em reuniões periódicas registradas em ata.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '3.1', 'r3', 1, 'Investigação qualitativa da relação entre composição da despesa e eficiência', 'Aprofundar a leitura sobre a relação entre composição da despesa (Pessoal e Encargos, outras despesas correntes e investimentos) e índice de eficiência acadêmico-orçamentária, com foco nas instituições em alerta (UEM e UNICENTRO).', 'SETI', '', '', 'Nota técnica com hipóteses explicativas e recomendações', 'Relação entre composição da despesa e eficiência compreendida nas instituições em alerta, com hipóteses registradas.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '3.2', 'r3', 2, 'Classificação de despesas em atividades-fim e atividades-meio', 'Desenvolver metodologia de classificação orçamentária que permita responder, de forma direta, à terceira pergunta norteadora do estudo.', 'SETI / SEFA', '', '', 'Metodologia de classificação validada e indicador incorporado ao painel', 'Proporção entre atividades-fim e atividades-meio disponível por instituição no painel.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '3.3', 'r3', 3, 'Resposta à quarta pergunta norteadora', 'Após a ampliação da série histórica (Bloco 1), produzir análise da evolução de cinco anos entre crescimento orçamentário e variação de indicadores de desempenho por IEES.', 'SETI', '', '', 'Nota técnica de evolução histórica orçamento x desempenho', 'Quarta pergunta norteadora do estudo respondida, com a evolução de cinco anos entre orçamento e desempenho.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('seti', 'p1', '3.4', 'r3', 4, 'Retomada do Índice de Desempenho da Formação', 'Reavaliar a viabilidade de construção do Índice de Desempenho da Formação (qualidade do emprego no entorno de cada universidade), condicionada à ampliação da granularidade regional das bases RAIS não identificada e CBO2 necessária ao cruzamento proposto. Decisão de não construção neste estudo registrada na Nota Metodológica da seção 3.1.', 'SETI', '', '', 'Nota técnica de viabilidade, a ser produzida quando houver granularidade de dados suficiente para o cruzamento regional', 'Viabilidade do Índice de Desempenho da Formação reavaliada quando as bases RAIS e CBO2 tiverem granularidade regional suficiente, com a decisão de construir ou não o índice registrada.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '1.1', 'r1', 1, 'Ampliação da série histórica de condição da malha', 'Disponibilizar levantamentos SAM de anos anteriores a 2024, por SR', 'DER', '', '', 'Série histórica de condição da malha por SR', 'Condição da malha por SR disponível em série histórica anterior a 2024, permitindo passar da leitura transversal para a leitura de evolução ao longo do tempo.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '1.2', 'r1', 2, 'Base de execução por contrato', 'Estruturar base com meta física prevista/executada, unidade de medida, datas de vigência e percentuais físico e financeiro executados, por contrato e SR', 'DER', '', '', 'Base de execução por contrato consolidada', 'Painel alimentado pela execução física e financeira de cada contrato, por SR, relacionando o valor liquidado à meta física prevista e executada.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '1.3', 'r1', 3, 'Dados de tráfego', 'Levantar intensidade de tráfego por trecho, com coordenadas GIS', 'DER', '', '', 'Base georreferenciada de tráfego', 'Perfil de tráfego por trecho incorporado à leitura de custo e de condição da malha, como um dos fatores estruturais que explicam a variação entre regionais.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '2.1', 'r2', 1, 'Rotina de leitura compartilhada', 'Instituir reuniões periódicas entre Diretoria Técnica, Diretoria de Operação e Superintendências Regionais para leitura conjunta dos indicadores', 'DER', '', '', 'Calendário de reuniões e atas de leitura', 'Diretoria Técnica, Diretoria de Operação e Superintendências Regionais lendo os indicadores do painel em conjunto, em reuniões periódicas registradas em ata.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '2.2', 'r2', 2, 'Incorporação ao ciclo orçamentário', 'Utilizar o painel como insumo técnico na priorização de contratos e alocação de recursos entre SRs', 'DER / SEFA', '', '', 'Rotina formal documentada no processo orçamentário', 'Priorização de contratos e alocação de recursos entre SRs apoiadas pelo painel como insumo técnico documentado, sem uso como critério automático de corte ou redistribuição.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '3.1', 'r3', 1, 'Rastreabilidade municipal do gasto', 'Confirmar, junto às áreas de gestão contratual, a situação dos municípios sem valor liquidado identificável (trechos concessionados, outras ações, ausência de segregação municipal) e avaliar a instituição de registro municipal obrigatório em novos contratos e aditivos', 'DER', '', '', 'Nota técnica de esclarecimento e proposta de registro municipal', 'Situação dos municípios sem valor liquidado identificável esclarecida e registro municipal avaliado para novos contratos e aditivos, ampliando a rastreabilidade territorial do gasto.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '3.2', 'r3', 2, 'Tipologia de serviço e pavimento', 'Aprofundar a leitura sobre a relação entre tipo de serviço (manutenção vs. recomposição), tipo de pavimento e custo unitário por SR', 'DER / Equipe de consultoria', '', '', 'Nota técnica com hipóteses explicativas', 'Diferenças de custo por quilômetro entre regionais compreendidas à luz do tipo de serviço e de pavimento, com hipóteses registradas antes de qualquer conclusão sobre eficiência relativa.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('der', 'p1', '3.3', 'r3', 3, 'Revisão de contratos emergenciais', 'Analisar a série de contratos emergenciais por SR como indicador antecedente de pressão futura', 'DER', '', '', 'Indicador incorporado à rotina de monitoramento', 'Participação dos contratos emergenciais acompanhada por SR como sinal antecedente de risco, com a hipótese de déficit de manutenção preventiva confirmada ou descartada.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '1.1', 'r1', 1, 'Definir o conjunto mínimo de informações a registrar por proposta', 'Definir, para os próximos chamamentos, um conjunto mínimo de informações a serem registradas de forma estruturada para cada proposta ao longo de todo o ciclo da parceria: identificação da OSC e do projeto; município e eixo de atuação; valores solicitado, aprovado e pago; público previsto e efetivamente atendido; metas e entregas previstas e realizadas; datas das principais etapas de tramitação; situação da execução; e resultados alcançados', '', '', '', 'Conjunto mínimo de informações por proposta definido para os próximos chamamentos, considerando as especificidades de cada edital.', 'Propostas registradas de forma estruturada ao longo de todo o ciclo da parceria, o que permite calcular o tempo médio de tramitação, o custo por beneficiário e por entrega e o cumprimento de metas.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '1.2', 'r1', 2, 'Criar página das parcerias no sítio eletrônico da SEDEF', 'Estruturar, como primeiro movimento, uma página específica no sítio eletrônico da SEDEF que funcione como ponto central de acesso às informações sobre as parcerias, reunindo os editais, cronogramas, resultados das etapas, organizações contempladas, valores transferidos e demais informações de acompanhamento disponíveis', '', '', '', 'Página das parcerias publicada no sítio eletrônico da SEDEF, com editais, cronogramas, resultados das etapas, organizações contempladas e valores transferidos.', 'OSCs, conselhos e cidadãos consultando em um só lugar as informações sobre os chamamentos, os recursos transferidos e o andamento das parcerias.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '1.3', 'r1', 3, 'Centralizar e integrar progressivamente as informações das parcerias', 'Reorganizar e padronizar as informações já produzidas pela Secretaria, hoje distribuídas entre bases administrativas, SISTAG, planos de trabalho, documentos em PDF e páginas do sítio eletrônico, e, conforme a necessidade e a viabilidade técnica, ampliar a integração entre os sistemas e bases usados na gestão das parcerias, tendo como referência o Portal de Parcerias Sociais do Estado de São Paulo', '', '', '', 'Informações das parcerias reorganizadas e padronizadas, com integração entre os sistemas e bases de gestão ampliada conforme a viabilidade técnica.', 'Equipes da SEDEF dispensadas de reunir e reconstruir as informações a cada novo ciclo de acompanhamento, com análises comparativas entre projetos, eixos e editais.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '2.1', 'r2', 1, 'Mapear os documentos exigidos de forma recorrente nos editais', 'Mapear os documentos exigidos de forma recorrente nos diferentes editais da SEDEF e avaliar quais podem ser reutilizados, por quanto tempo permanecem válidos, quais informações precisam ser atualizadas a cada chamamento e quais verificações devem continuar ocorrendo individualmente por proposta', '', '', '', 'Diagnóstico dos documentos institucionais exigidos de forma recorrente, com a validade possível de cada um e as verificações que permanecem individuais por proposta.', 'Base definida para decidir quais documentos já verificados podem ser aproveitados em diferentes propostas e chamamentos.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '2.2', 'r2', 2, 'Definir e implantar a solução de aproveitamento de documentos pré-validados', 'A partir do diagnóstico, definir a alternativa mais adequada, que pode variar de ajustes nos procedimentos internos e no SISTAG até a implantação de cadastro único pré-validado para OSCs parceiras, com período de validade e procedimentos de atualização, observado o marco normativo estadual e tendo como referência o Cadastro Único das Entidades Parceiras do Terceiro Setor (CENTS) do Município de São Paulo', '', '', '', 'Solução de aproveitamento de documentos pré-validados definida e implantada, por ajuste nos procedimentos e no SISTAG ou por cadastro próprio.', 'OSCs que participam de mais de uma proposta, 308 entre as aptas no Edital nº 005/2024 (44,4%), sem reapresentar documentos institucionais ainda válidos, e análise documental concentrada nos requisitos específicos de cada proposta.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '3.1', 'r3', 1, 'Disponibilizar os modelos editáveis em repositório próprio', 'Criar um repositório de modelos editáveis, organizado por chamamento e etapa do processo, com os documentos necessários à participação das OSCs, como declarações, modelo de plano de trabalho e minuta do Termo de Fomento, em formatos como .docx ou PDF preenchível e acompanhados de orientações objetivas sobre finalidade e preenchimento', '', '', '', 'Repositório de modelos editáveis disponibilizado, organizado por chamamento e etapa do processo, com orientações de preenchimento.', 'Organizações preparando as propostas sem precisar localizar e adaptar os modelos dentro do arquivo do edital, com menos erros de preenchimento e formatação.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '3.2', 'r3', 2, 'Desenvolver pacote de orientação ao proponente', 'Reunir guia de participação, perguntas frequentes, orientações para elaboração do plano de trabalho, explicações sobre os critérios de avaliação e informações sobre as etapas posteriores à seleção, atualizando o conteúdo periodicamente com os motivos recorrentes de não avanço das propostas, as dúvidas das organizações e as dificuldades identificadas pelas equipes de análise', '', '', '', 'Pacote de orientação ao proponente disponibilizado, com guia de participação, perguntas frequentes e orientações sobre o plano de trabalho e os critérios de avaliação.', 'Orientações que respondem às dificuldades efetivamente observadas nos chamamentos da SEDEF, e não apenas explicam o edital de forma geral.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '3.3', 'r3', 3, 'Consolidar referencial operacional das parcerias com OSCs', 'Utilizar o Manual MROSC: Do Planejamento à Prestação de Contas, publicado pelo Governo Federal em 2025, como referência complementar para as equipes e as OSCs parceiras e, em etapa posterior, avaliar a elaboração de orientações próprias, adaptadas ao Decreto Estadual nº 3.513/2016, aos procedimentos da Secretaria e ao SISTAG', '', '', '', 'Referencial operacional das parcerias, do planejamento à prestação de contas, adotado como referência e adaptado à regulamentação estadual.', 'Gestores e organizações parceiras com orientações operacionais que traduzem a regulamentação estadual em procedimentos para cada etapa da parceria.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '4.1', 'r4', 1, 'Elaborar materiais escritos de orientação às OSCs parceiras', 'Desenvolver materiais escritos de apoio à gestão dos recursos pelas OSCs, com conteúdo prático ligado à execução dos Termos de Fomento: organização documental, controle financeiro do projeto, conciliação de extratos, planejamento de desembolsos, acompanhamento das metas do plano de trabalho e preparação da prestação de contas, aproveitando dúvidas recorrentes e dificuldades identificadas no acompanhamento das parcerias', '', '', '', 'Materiais escritos de orientação disponibilizados às OSCs parceiras, nos temas de gestão dos recursos, metas e prestação de contas.', 'OSCs administrando os recursos de forma aderente ao plano de trabalho, com registros mais consistentes sobre o que foi executado, gasto e entregue.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '4.2', 'r4', 2, 'Promover ações de capacitação das OSCs, conforme a demanda', 'Conforme a demanda observada e a capacidade institucional disponível, evoluir dos materiais escritos para ações de capacitação direcionadas às organizações contempladas, priorizando os pontos de maior dificuldade e um apoio proporcional às necessidades', '', '', '', 'Ações de capacitação realizadas com as OSCs contempladas, nos pontos de maior dificuldade identificados.', 'Menos dificuldades na execução dos projetos e na prestação de contas, e maior capacidade da SEDEF de relacionar recursos transferidos e entregas realizadas.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '5.1', 'r5', 1, 'Definir indicadores e dados a registrar na preparação de cada edital', 'Na preparação de futuros editais, definir previamente as perguntas de gestão, as dimensões de desempenho a acompanhar e as informações a registrar para sua mensuração, avaliando e adaptando os seis indicadores do estudo às características de cada instrumento e complementando-os com dados sobre beneficiários, metas e entregas', '', '', '', 'Perguntas de gestão, indicadores de acompanhamento e dados a registrar definidos na concepção de cada novo edital.', 'Monitoramento incorporado desde a concepção do chamamento, sem indicadores construídos depois apenas com as informações que estiverem disponíveis.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '5.2', 'r5', 2, 'Indicar ponto focal para a atualização do Painel Executivo', 'Definir, na SEDEF, um responsável ou ponto focal pela atualização das bases e pela manutenção das informações do Painel Executivo do Edital nº 005/2024 e, caso se amplie o uso institucional ou se avalie a publicação da ferramenta, definir também a periodicidade de manutenção e os procedimentos de validação dos dados', '', '', '', 'Ponto focal indicado e orientado para atualizar as bases do painel, com periodicidade e procedimentos de validação definidos.', 'Painel em uso após o encerramento do estudo, com informações atuais e confiáveis para o acompanhamento do edital.', null, null, null, null, 'relatorio', 'nao_iniciada'),
  ('sedef', 'p1', '6.1', 'r6', 1, 'Considerar os indicadores dos editais na discussão da proposta orçamentária', 'Considerar, nos próximos ciclos, os indicadores e as evidências produzidos sobre os editais de transferência de recursos a OSCs nas discussões da proposta orçamentária entre a SEFA e a SEDEF, especialmente ao avaliar manutenção, ampliação ou redimensionamento dos recursos, sem criar critérios automáticos de alocação', '', '', '', 'Indicadores e evidências dos editais incorporados, de forma documentada, às discussões da proposta orçamentária da Ação 8418 entre a SEFA e a SEDEF.', 'Discussão orçamentária que avança da leitura da execução financeira para a análise do desempenho dos instrumentos financiados, com uso analítico e complementar dos indicadores.', null, null, null, null, 'relatorio', 'nao_iniciada')
on conflict (org_id, estudo_id, codigo) do nothing;
